  "lib/games/lemon_game.dart": "import 'dart:async';\nimport 'dart:math';\nimport 'package:archbtw_sh/global/colors.dart';\nimport 'package:archbtw_sh/global/site_music_controller.dart';\nimport 'package:archbtw_sh/widgets/in_game_music_hud.dart';\nimport 'package:audioplayers/audioplayers.dart';\nimport 'package:flutter/material.dart';\n\nenum LemonItemType {\n  lemon,\n  crosstopPill,\n  elixirPotion,\n  blueCandle,\n  coffeeCup,\n  cherrySeven,\n}\n\nextension LemonItemTypeMeta on LemonItemType {\n  Color get themeColor {\n    switch (this) {\n      case LemonItemType.lemon:\n        return const Color(0xFFFACC15);\n      case LemonItemType.crosstopPill:\n        return const Color(0xFFEF4444);\n      case LemonItemType.elixirPotion:\n        return const Color(0xFFA855F7);\n      case LemonItemType.blueCandle:\n        return const Color(0xFF38BDF8);\n      case LemonItemType.coffeeCup:\n        return const Color(0xFFD97706);\n      case LemonItemType.cherrySeven:\n        return const Color(0xFFEC4899);\n    }\n  }\n\n  String get label {\n    switch (this) {\n      case LemonItemType.lemon:\n        return 'LEMON';\n      case LemonItemType.crosstopPill:\n        return 'CROSSTOP';\n      case LemonItemType.elixirPotion:\n        return 'ELIXIR';\n      case LemonItemType.blueCandle:\n        return 'CANDLEWAX';\n      case LemonItemType.coffeeCup:\n        return 'COLOMBIAN';\n      case LemonItemType.cherrySeven:\n        return 'CHERRY 7';\n    }\n  }\n}\n\nclass Pill {\n  final LemonItemType type;\n  final String id;\n\n  Pill(this.type) : id = UniqueKey().toString();\n\n  Color get color => type.themeColor;\n}\n\nclass LemonsGame extends StatefulWidget {\n  const LemonsGame({super.key});\n\n  @override\n  State<LemonsGame> createState() => _LemonsGameState();\n}\n\nclass _LemonsGameState extends State<LemonsGame> {\n  final AudioPlayer _audioPlayer = AudioPlayer();\n  final List<String> _playlist = [\n    'almost_intelligent.m4a',\n    'crosstops.m4a',\n    'c_u_next_tuesday.m4a',\n    'drinking_outta_cups.m4a',\n    'elixir.m4a',\n    'florence.m4a',\n    'it_seemed_like_a_good_idea_at_the_time.m4a',\n    'you_call_this_mercy.m4a',\n    'midnight_oil.m4a',\n    'i_may_not_be_a_smart_man_but_i_know_what_love_is.m4a',\n    'lets_take_it_apart_and_put_it_back_together.m4a',\n    'and_thats_how_it_happened.m4a',\n    'third_times_a_charm.m4a',\n  ];\n\n  int _currentTrackIndex = 0;\n  bool _isMusicPlaying = true;\n  StreamSubscription? _playerCompleteSubscription;\n  StreamSubscription? _playerStateSubscription;\n\n  final int _rows = 8;\n  final int _cols = 5;\n\n  final List<LemonItemType> _itemTypes = LemonItemType.values;\n\n  late List<List<Pill?>> _grid;\n  Point<int>? _selectedPoint;\n\n  int _score = 0;\n  bool _isWon = false;\n  bool _isGameOver = false;\n  bool _isProcessing = false;\n\n  Timer? _gameTimer;\n  int _secondsRemaining = 180;\n\n  @override\n  void initState() {\n    super.initState();\n    _initGrid(resetScore: true);\n    _setupAudioPlayer();\n  }\n\n  @override\n  void dispose() {\n    SiteMusicController.instance.exitGame();\n    _playerCompleteSubscription?.cancel();\n    _playerStateSubscription?.cancel();\n    _audioPlayer.dispose();\n    _gameTimer?.cancel();\n    super.dispose();\n  }\n\n  void _setupAudioPlayer() {\n    SiteMusicController.instance.enterGame();\n    configureBackgroundAudioContext();\n    _audioPlayer.setReleaseMode(ReleaseMode.release);\n\n    _playerCompleteSubscription = _audioPlayer.onPlayerComplete.listen((event) {\n      _playNextTrack();\n    });\n    _playerStateSubscription = _audioPlayer.onPlayerStateChanged.listen((state) {\n      if (mounted) {\n        setState(() {\n          _isMusicPlaying = state == PlayerState.playing;\n        });\n      }\n    });\n\n    _playTrackAt(Random().nextInt(_playlist.length));\n  }\n\n  Future<void> _playTrackAt(int index) async {\n    if (_playlist.isEmpty) return;\n    final int wrapped = (index % _playlist.length + _playlist.length) % _playlist.length;\n    if (mounted) {\n      setState(() {\n        _currentTrackIndex = wrapped;\n        _isMusicPlaying = true;\n      });\n    }\n    final nextSong = _playlist[wrapped];\n\n    try {\n      final fullPath = 'music/lemons/\$nextSong';\n      await _audioPlayer.setSource(AssetSource(fullPath));\n      await _audioPlayer.setVolume(0.5);\n      await _audioPlayer.resume();\n    } catch (e) {\n      debugPrint('Audio Error: \$e');\n    }\n  }\n\n  Future<void> _playNextTrack() async {\n    await _playTrackAt(_currentTrackIndex + 1);\n  }\n\n  Future<void> _playPreviousTrack() async {\n    await _playTrackAt(_currentTrackIndex - 1);\n  }\n\n  Future<void> _togglePlayPause() async {\n    try {\n      if (_isMusicPlaying) {\n        await _audioPlayer.pause();\n        if (mounted) setState(() => _isMusicPlaying = false);\n      } else {\n        await _audioPlayer.resume();\n        if (mounted) setState(() => _isMusicPlaying = true);\n      }\n    } catch (e) {\n      debugPrint('Audio Toggle Error: \$e');\n    }\n  }\n\n  Future<void> _cleanupStragglers() async {\n    final Map<LemonItemType, int> typeCounts = {};\n    for (final row in _grid) {\n      for (final item in row) {\n        if (item != null) {\n          typeCounts[item.type] = (typeCounts[item.type] ?? 0) + 1;\n        }\n      }\n    }\n\n    final List<LemonItemType> doomedTypes = [];\n    typeCounts.forEach((type, count) {\n      if (count > 0 && count < 3) {\n        doomedTypes.add(type);\n      }\n    });\n\n    if (doomedTypes.isEmpty) return;\n\n    bool changed = false;\n    setState(() {\n      for (int y = 0; y < _rows; y++) {\n        for (int x = 0; x < _cols; x++) {\n          final item = _grid[y][x];\n          if (item != null && doomedTypes.contains(item.type)) {\n            _grid[y][x] = null;\n            _score += 5;\n            changed = true;\n          }\n        }\n      }\n    });\n\n    if (changed) {\n      await Future.delayed(const Duration(milliseconds: 200));\n      await _applyGravity();\n      await _resolveMatches();\n    }\n  }\n\n  void _startTimer() {\n    _gameTimer?.cancel();\n    _secondsRemaining = 180;\n    _gameTimer = Timer.periodic(const Duration(seconds: 1), (timer) {\n      if (!mounted) return;\n      setState(() {\n        if (_secondsRemaining > 0) {\n          _secondsRemaining--;\n        } else {\n          _isGameOver = true;\n          _gameTimer?.cancel();\n        }\n      });\n    });\n  }\n\n  void _initGrid({bool resetScore = true}) {\n    final rng = Random();\n    _grid = List.generate(_rows, (_) => List<Pill?>.filled(_cols, null));\n\n    for (int y = 0; y < _rows; y++) {\n      for (int x = 0; x < _cols; x++) {\n        LemonItemType proposedType;\n        do {\n          proposedType = _itemTypes[rng.nextInt(_itemTypes.length)];\n        } while (!_isMatchSafe(_grid, x, y, proposedType, isTopDown: true));\n\n        _grid[y][x] = Pill(proposedType);\n      }\n    }\n\n    setState(() {\n      if (resetScore) _score = 0;\n      _isWon = false;\n      _isGameOver = false;\n      _isProcessing = false;\n      _selectedPoint = null;\n    });\n\n    _startTimer();\n  }\n\n  Future<void> _shuffleGrid() async {\n    if (_isProcessing || _isWon || _isGameOver) return;\n\n    setState(() {\n      _isProcessing = true;\n    });\n\n    final List<Pill> availableItems = [];\n    for (final row in _grid) {\n      for (final item in row) {\n        if (item != null) availableItems.add(item);\n      }\n    }\n    availableItems.shuffle();\n\n    final List<List<Pill?>> newGrid = List.generate(\n      _rows,\n      (_) => List<Pill?>.filled(_cols, null),\n    );\n\n    int itemIndex = 0;\n\n    for (int y = _rows - 1; y >= 0; y--) {\n      for (int x = 0; x < _cols; x++) {\n        if (itemIndex >= availableItems.length) break;\n\n        int foundIndex = -1;\n\n        for (int k = itemIndex; k < availableItems.length; k++) {\n          if (_isMatchSafe(\n            newGrid,\n            x,\n            y,\n            availableItems[k].type,\n            isTopDown: false,\n          )) {\n            foundIndex = k;\n            break;\n          }\n        }\n\n        if (foundIndex != -1) {\n          final temp = availableItems[itemIndex];\n          availableItems[itemIndex] = availableItems[foundIndex];\n          availableItems[foundIndex] = temp;\n        }\n\n        newGrid[y][x] = availableItems[itemIndex];\n        itemIndex++;\n      }\n    }\n\n    setState(() {\n      _grid = newGrid;\n      _selectedPoint = null;\n    });\n\n    await Future.delayed(const Duration(milliseconds: 500));\n    await _resolveMatches();\n\n    if (mounted) {\n      setState(() {\n        _isProcessing = false;\n      });\n    }\n  }\n\n  bool _isMatchSafe(\n    List<List<Pill?>> tempGrid,\n    int x,\n    int y,\n    LemonItemType type, {\n    required bool isTopDown,\n  }) {\n    if (x >= 2) {\n      if (tempGrid[y][x - 1]?.type == type &&\n          tempGrid[y][x - 2]?.type == type) {\n        return false;\n      }\n    }\n\n    if (isTopDown) {\n      if (y >= 2) {\n        if (tempGrid[y - 1][x]?.type == type &&\n            tempGrid[y - 2][x]?.type == type) {\n          return false;\n        }\n      }\n\n      if (x >= 2 && y >= 2) {\n        if (tempGrid[y - 1][x - 1]?.type == type &&\n            tempGrid[y - 2][x - 2]?.type == type) {\n          return false;\n        }\n      }\n      if (x <= _cols - 3 && y >= 2) {\n        if (tempGrid[y - 1][x + 1]?.type == type &&\n            tempGrid[y - 2][x + 2]?.type == type) {\n          return false;\n        }\n      }\n    } else {\n      if (y <= _rows - 3) {\n        if (tempGrid[y + 1][x]?.type == type &&\n            tempGrid[y + 2][x]?.type == type) {\n          return false;\n        }\n      }\n\n      if (x >= 2 && y <= _rows - 3) {\n        if (tempGrid[y + 1][x - 1]?.type == type &&\n            tempGrid[y + 2][x - 2]?.type == type) {\n          return false;\n        }\n      }\n\n      if (x <= _cols - 3 && y <= _rows - 3) {\n        if (tempGrid[y + 1][x + 1]?.type == type &&\n            tempGrid[y + 2][x + 2]?.type == type) {\n          return false;\n        }\n      }\n    }\n\n    return true;\n  }\n\n  void _handleTap(int x, int y) {\n    if (_isProcessing || _isWon || _isGameOver || _grid[y][x] == null) return;\n\n    setState(() {\n      if (_selectedPoint == null) {\n        _selectedPoint = Point(x, y);\n      } else if (_selectedPoint!.x == x && _selectedPoint!.y == y) {\n        _selectedPoint = null;\n      } else {\n        final dx = (x - _selectedPoint!.x).abs();\n        final dy = (y - _selectedPoint!.y).abs();\n\n        final isNeighbor = dx <= 1 && dy <= 1 && !(dx == 0 && dy == 0);\n\n        if (isNeighbor) {\n          _attemptSwap(_selectedPoint!, Point(x, y));\n          _selectedPoint = null;\n        } else {\n          _selectedPoint = Point(x, y);\n        }\n      }\n    });\n  }\n\n  Future<void> _attemptSwap(Point<int> p1, Point<int> p2) async {\n    setState(() {\n      _isProcessing = true;\n      final temp = _grid[p1.y][p1.x];\n      _grid[p1.y][p1.x] = _grid[p2.y][p2.x];\n      _grid[p2.y][p2.x] = temp;\n    });\n\n    await Future.delayed(const Duration(milliseconds: 300));\n\n    final bool hasMatch = await _resolveMatches();\n\n    if (!hasMatch) {\n      if (mounted) {\n        setState(() {\n          final temp = _grid[p1.y][p1.x];\n          _grid[p1.y][p1.x] = _grid[p2.y][p2.x];\n          _grid[p2.y][p2.x] = temp;\n          _isProcessing = false;\n        });\n      }\n    }\n  }\n\n  Future<bool> _resolveMatches({bool initial = false}) async {\n    final Set<Point<int>> matchedPoints = {};\n\n    LemonItemType? getType(int x, int y) => _grid[y][x]?.type;\n\n    for (int y = 0; y < _rows; y++) {\n      for (int x = 0; x < _cols - 2; x++) {\n        final t = getType(x, y);\n        if (t == null) continue;\n        if (getType(x + 1, y) == t && getType(x + 2, y) == t) {\n          matchedPoints.addAll([Point(x, y), Point(x + 1, y), Point(x + 2, y)]);\n          int k = x + 3;\n          while (k < _cols && getType(k, y) == t) {\n            matchedPoints.add(Point(k, y));\n            k++;\n          }\n        }\n      }\n    }\n\n    for (int x = 0; x < _cols; x++) {\n      for (int y = 0; y < _rows - 2; y++) {\n        final t = getType(x, y);\n        if (t == null) continue;\n        if (getType(x, y + 1) == t && getType(x, y + 2) == t) {\n          matchedPoints.addAll([Point(x, y), Point(x, y + 1), Point(x, y + 2)]);\n          int k = y + 3;\n          while (k < _rows && getType(x, k) == t) {\n            matchedPoints.add(Point(x, k));\n            k++;\n          }\n        }\n      }\n    }\n\n    for (int y = 0; y < _rows - 2; y++) {\n      for (int x = 0; x < _cols - 2; x++) {\n        final t = getType(x, y);\n        if (t == null) continue;\n        if (getType(x + 1, y + 1) == t && getType(x + 2, y + 2) == t) {\n          matchedPoints.addAll([\n            Point(x, y),\n            Point(x + 1, y + 1),\n            Point(x + 2, y + 2),\n          ]);\n          int k = 3;\n          while (y + k < _rows &&\n              x + k < _cols &&\n              getType(x + k, y + k) == t) {\n            matchedPoints.add(Point(x + k, y + k));\n            k++;\n          }\n        }\n      }\n    }\n\n    for (int y = 0; y < _rows - 2; y++) {\n      for (int x = 2; x < _cols; x++) {\n        final t = getType(x, y);\n        if (t == null) continue;\n        if (getType(x - 1, y + 1) == t && getType(x - 2, y + 2) == t) {\n          matchedPoints.addAll([\n            Point(x, y),\n            Point(x - 1, y + 1),\n            Point(x - 2, y + 2),\n          ]);\n          int k = 3;\n          while (y + k < _rows && x - k >= 0 && getType(x - k, y + k) == t) {\n            matchedPoints.add(Point(x - k, y + k));\n            k++;\n          }\n        }\n      }\n    }\n\n    if (matchedPoints.isNotEmpty) {\n      if (!initial) {\n        if (mounted) {\n          setState(() {\n            for (final p in matchedPoints) {\n              _grid[p.y][p.x] = null;\n            }\n            _score += matchedPoints.length * 10;\n          });\n        }\n        await Future.delayed(const Duration(milliseconds: 300));\n      } else {\n        for (final p in matchedPoints) {\n          _grid[p.y][p.x] = null;\n        }\n      }\n\n      await _applyGravity();\n      await _resolveMatches(initial: initial);\n      return true;\n    }\n\n    if (!initial) {\n      await _cleanupStragglers();\n      _checkWinCondition();\n    }\n\n    if (!initial && mounted) {\n      setState(() {\n        _isProcessing = false;\n      });\n    }\n    return false;\n  }\n\n  void _checkWinCondition() {\n    bool isEmpty = true;\n    for (final row in _grid) {\n      for (final item in row) {\n        if (item != null) {\n          isEmpty = false;\n          break;\n        }\n      }\n    }\n    if (isEmpty && !_isWon) {\n      setState(() {\n        _isWon = true;\n        _gameTimer?.cancel();\n      });\n    }\n  }\n\n  Future<void> _applyGravity() async {\n    bool moved = false;\n    for (int x = 0; x < _cols; x++) {\n      int writeIdx = _rows - 1;\n      for (int readIdx = _rows - 1; readIdx >= 0; readIdx--) {\n        if (_grid[readIdx][x] != null) {\n          if (writeIdx != readIdx) {\n            _grid[writeIdx][x] = _grid[readIdx][x];\n            _grid[readIdx][x] = null;\n            moved = true;\n          }\n          writeIdx--;\n        }\n      }\n    }\n    if (moved && mounted) {\n      setState(() {});\n      await Future.delayed(const Duration(milliseconds: 300));\n    }\n  }\n\n  String get _timerString {\n    final mins = (_secondsRemaining ~/ 60).toString().padLeft(2, '0');\n    final secs = (_secondsRemaining % 60).toString().padLeft(2, '0');\n    return '\$mins:\$secs';\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      backgroundColor: const Color(0xFF0B1021),\n      appBar: AppBar(\n        backgroundColor: const Color(0xFF070B17),\n        elevation: 0,\n        leading: IconButton(\n          icon: const Icon(Icons.arrow_back, color: kAccentColor),\n          onPressed: () => Navigator.of(context).pop(),\n        ),\n        title: Text(\n          _isWon\n              ? 'NO MORE MELANCHOLY'\n              : (_isGameOver ? 'TIMEOUT' : _timerString),\n          style: TextStyle(\n            fontFamily: 'JetBrainsMono',\n            color: _isWon\n                ? const Color(0xFFFACC15)\n                : (_isGameOver ? Colors.red : kAccentColor),\n            fontSize: 18,\n            fontWeight: FontWeight.bold,\n          ),\n        ),\n        actions: [\n          Center(\n            child: Padding(\n              padding: const EdgeInsets.only(right: 16.0),\n              child: Container(\n                padding: const EdgeInsets.symmetric(\n                  horizontal: 10,\n                  vertical: 5,\n                ),\n                decoration: BoxDecoration(\n                  color: Colors.white.withValues(alpha: 0.08),\n                  borderRadius: BorderRadius.circular(8),\n                  border: Border.all(\n                    color: const Color(0xFFFACC15).withValues(alpha: 0.6),\n                  ),\n                ),\n                child: Text(\n                  'SCORE: \$_score',\n                  style: const TextStyle(\n                    fontFamily: 'JetBrainsMono',\n                    color: Colors.white,\n                    fontWeight: FontWeight.bold,\n                    fontSize: 13,\n                  ),\n                ),\n              ),\n            ),\n          ),\n        ],\n        bottom: PreferredSize(\n          preferredSize: const Size.fromHeight(36),\n          child: InGameMusicHud(\n            currentTrack: _playlist[_currentTrackIndex],\n            isPlaying: _isMusicPlaying,\n            accentColor: const Color(0xFFFACC15),\n            onPrevious: _playPreviousTrack,\n            onPlayPause: _togglePlayPause,\n            onNext: _playNextTrack,\n          ),\n        ),\n      ),\n      floatingActionButton: (!_isWon && !_isGameOver)\n          ? FloatingActionButton(\n              tooltip: 'Shuffle Board',\n              onPressed: _shuffleGrid,\n              backgroundColor: const Color(0xFFFACC15),\n              child: const Icon(Icons.shuffle, color: Colors.black),\n            )\n          : null,\n      body: Container(\n        decoration: const BoxDecoration(\n          gradient: RadialGradient(\n            center: Alignment(0.0, -0.3),\n            radius: 1.2,\n            colors: [\n              Color(0xFF1E1B4B),\n              Color(0xFF0F172A),\n              Color(0xFF060913),\n            ],\n          ),\n        ),\n        child: Stack(\n          children: [\n            if (_isWon) _buildWinScreen(),\n            if (_isGameOver && !_isWon) _buildLoseScreen(),\n            if (!_isWon && !_isGameOver) _buildGameLayout(),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildWinScreen() {\n    return Center(\n      child: Container(\n        margin: const EdgeInsets.all(24),\n        padding: const EdgeInsets.all(28),\n        decoration: BoxDecoration(\n          color: const Color(0xFF0F172A).withValues(alpha: 0.92),\n          borderRadius: BorderRadius.circular(18),\n          border: Border.all(color: const Color(0xFFFACC15), width: 3),\n          boxShadow: [\n            BoxShadow(\n              color: const Color(0xFFFACC15).withValues(alpha: 0.25),\n              blurRadius: 20,\n            ),\n          ],\n        ),\n        child: Column(\n          mainAxisSize: MainAxisSize.min,\n          children: [\n            const SizedBox(\n              width: 90,\n              height: 90,\n              child: CustomPaint(\n                painter: _LemonItemPainter(type: LemonItemType.lemon),\n              ),\n            ),\n            const SizedBox(height: 18),\n            const Text(\n              \"LIFE'S LEMONS CLEARED!\",\n              textAlign: TextAlign.center,\n              style: TextStyle(\n                fontFamily: 'JetBrainsMono',\n                color: Color(0xFFFACC15),\n                fontWeight: FontWeight.bold,\n                fontSize: 22,\n              ),\n            ),\n            const SizedBox(height: 28),\n            ElevatedButton(\n              style: ElevatedButton.styleFrom(\n                padding: const EdgeInsets.symmetric(\n                  horizontal: 32,\n                  vertical: 16,\n                ),\n                backgroundColor: const Color(0xFFFACC15),\n                foregroundColor: Colors.black,\n              ),\n              onPressed: () => _initGrid(resetScore: false),\n              child: const Text(\n                'squeeze another batch',\n                style: TextStyle(\n                  fontFamily: 'JetBrainsMono',\n                  fontWeight: FontWeight.bold,\n                  fontSize: 16,\n                ),\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildLoseScreen() {\n    return Center(\n      child: Container(\n        margin: const EdgeInsets.all(24),\n        padding: const EdgeInsets.all(28),\n        decoration: BoxDecoration(\n          color: const Color(0xFF0F172A).withValues(alpha: 0.92),\n          borderRadius: BorderRadius.circular(18),\n          border: Border.all(color: Colors.redAccent, width: 3),\n        ),\n        child: Column(\n          mainAxisSize: MainAxisSize.min,\n          children: [\n            const Icon(Icons.error_outline, color: Colors.redAccent, size: 76),\n            const SizedBox(height: 20),\n            const Text(\n              'CONNECTION TIMED OUT',\n              textAlign: TextAlign.center,\n              style: TextStyle(\n                fontFamily: 'JetBrainsMono',\n                color: Colors.redAccent,\n                fontWeight: FontWeight.bold,\n                fontSize: 22,\n              ),\n            ),\n            const SizedBox(height: 28),\n            ElevatedButton(\n              style: ElevatedButton.styleFrom(\n                padding: const EdgeInsets.symmetric(\n                  horizontal: 32,\n                  vertical: 16,\n                ),\n                backgroundColor: const Color(0xFFFACC15),\n                foregroundColor: Colors.black,\n              ),\n              onPressed: () => _initGrid(resetScore: true),\n              child: const Text(\n                'retry',\n                style: TextStyle(\n                  fontFamily: 'JetBrainsMono',\n                  fontWeight: FontWeight.bold,\n                  fontSize: 16,\n                ),\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildGameLayout() {\n    return LayoutBuilder(\n      builder: (context, constraints) {\n        final double maxWidth = constraints.maxWidth - 20;\n        final double maxHeight = constraints.maxHeight - 20;\n\n        double cellSize = maxWidth / _cols;\n        if (cellSize * _rows > maxHeight) {\n          cellSize = maxHeight / _rows;\n        }\n\n        final double boardWidth = cellSize * _cols;\n        final double boardHeight = cellSize * _rows;\n        final double xOffset = (constraints.maxWidth - boardWidth) / 2;\n        final double yOffset = (constraints.maxHeight - boardHeight) / 2;\n\n        final List<Widget> gridWidgets = [\n          // Cartoon Board Frame\n          Positioned(\n            left: xOffset - 6,\n            top: yOffset - 6,\n            width: boardWidth + 12,\n            height: boardHeight + 12,\n            child: Container(\n              decoration: BoxDecoration(\n                color: const Color(0xFF090D1A).withValues(alpha: 0.85),\n                borderRadius: BorderRadius.circular(16),\n                border: Border.all(\n                  color: const Color(0xFF334155),\n                  width: 3,\n                ),\n                boxShadow: [\n                  BoxShadow(\n                    color: Colors.black.withValues(alpha: 0.6),\n                    blurRadius: 16,\n                    offset: const Offset(0, 6),\n                  ),\n                ],\n              ),\n            ),\n          ),\n        ];\n\n        for (int y = 0; y < _rows; y++) {\n          for (int x = 0; x < _cols; x++) {\n            gridWidgets.add(\n              Positioned(\n                left: xOffset + (x * cellSize),\n                top: yOffset + (y * cellSize),\n                width: cellSize,\n                height: cellSize,\n                child: Container(\n                  margin: const EdgeInsets.all(2.5),\n                  decoration: BoxDecoration(\n                    color: const Color(0xFF1E293B).withValues(alpha: 0.45),\n                    border: Border.all(color: Colors.white12, width: 1.2),\n                    borderRadius: BorderRadius.circular(12),\n                  ),\n                  child: GestureDetector(\n                    behavior: HitTestBehavior.translucent,\n                    onTap: () => _handleTap(x, y),\n                  ),\n                ),\n              ),\n            );\n          }\n        }\n\n        for (int y = 0; y < _rows; y++) {\n          for (int x = 0; x < _cols; x++) {\n            final item = _grid[y][x];\n            if (item == null) continue;\n\n            gridWidgets.add(\n              AnimatedPositioned(\n                key: Key(item.id),\n                duration: const Duration(milliseconds: 300),\n                curve: Curves.easeInOutBack,\n                left: xOffset + (x * cellSize),\n                top: yOffset + (y * cellSize),\n                width: cellSize,\n                height: cellSize,\n                child: IgnorePointer(\n                  child: _buildCartoonItemCell(x, y, cellSize, item),\n                ),\n              ),\n            );\n          }\n        }\n\n        return Stack(children: gridWidgets);\n      },\n    );\n  }\n\n  Widget _buildCartoonItemCell(int x, int y, double size, Pill item) {\n    final bool isSelected =\n        _selectedPoint != null &&\n        _selectedPoint!.x == x &&\n        _selectedPoint!.y == y;\n    final Color baseColor = item.color;\n\n    return Center(\n      child: AnimatedScale(\n        scale: isSelected ? 1.08 : 1.0,\n        duration: const Duration(milliseconds: 140),\n        child: SizedBox(\n          width: size * 0.90,\n          height: size * 0.90,\n          child: Container(\n            decoration: BoxDecoration(\n              gradient: RadialGradient(\n                center: const Alignment(-0.3, -0.35),\n                radius: 1.0,\n                colors: [\n                  Color.lerp(baseColor, Colors.white, 0.32)!,\n                  baseColor.withValues(alpha: 0.85),\n                  Color.lerp(baseColor, Colors.black, 0.45)!,\n                ],\n              ),\n              borderRadius: BorderRadius.circular(size * 0.24),\n              border: Border.all(\n                color: isSelected ? Colors.white : const Color(0xFF0F172A),\n                width: isSelected ? 3.2 : 2.2,\n              ),\n              boxShadow: [\n                if (isSelected)\n                  BoxShadow(\n                    color: baseColor.withValues(alpha: 0.85),\n                    blurRadius: 14,\n                    spreadRadius: 2,\n                  ),\n                BoxShadow(\n                  color: Colors.black.withValues(alpha: 0.45),\n                  offset: const Offset(0, 3),\n                  blurRadius: 4,\n                ),\n              ],\n            ),\n            child: Padding(\n              padding: EdgeInsets.all(size * 0.11),\n              child: CustomPaint(\n                painter: _LemonItemPainter(type: item.type),\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}\n\nclass _LemonItemPainter extends CustomPainter {\n  final LemonItemType type;\n\n  const _LemonItemPainter({required this.type});\n\n  @override\n  void paint(Canvas canvas, Size size) {\n    final Offset c = size.center(Offset.zero);\n    final double r = min(size.width, size.height) * 0.46;\n\n    final Paint outline = Paint()\n      ..color = const Color(0xFF0F172A)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = (r * 0.11).clamp(1.6, 3.0)\n      ..strokeJoin = StrokeJoin.round\n      ..strokeCap = StrokeCap.round;\n\n    switch (type) {\n      case LemonItemType.lemon:\n        // \"No more melancholy, only life's lemons\"\n        // Detailed cartoon lemon with tips, green leaf, and glossy shine\n        canvas.save();\n        canvas.translate(c.dx, c.dy);\n        canvas.rotate(-0.35);\n\n        final Path lemonBody = Path()\n          ..moveTo(-r * 1.05, 0)\n          ..quadraticBezierTo(-r * 0.75, -r * 0.78, 0, -r * 0.72)\n          ..quadraticBezierTo(r * 0.75, -r * 0.78, r * 1.05, 0)\n          ..quadraticBezierTo(r * 0.75, r * 0.78, 0, r * 0.72)\n          ..quadraticBezierTo(-r * 0.75, r * 0.78, -r * 1.05, 0)\n          ..close();\n\n        canvas.drawPath(\n          lemonBody,\n          Paint()..color = const Color(0xFFFDE047),\n        );\n        // Bottom shading arc\n        canvas.drawArc(\n          Rect.fromCenter(\n            center: Offset(0, r * 0.1),\n            width: r * 1.6,\n            height: r * 1.0,\n          ),\n          0.1,\n          pi - 0.2,\n          false,\n          Paint()..color = const Color(0xFFEAB308),\n        );\n        canvas.drawPath(lemonBody, outline);\n\n        // Specular highlight\n        canvas.drawArc(\n          Rect.fromCenter(\n            center: Offset(-r * 0.15, -r * 0.22),\n            width: r * 1.1,\n            height: r * 0.5,\n          ),\n          pi + 0.3,\n          1.4,\n          false,\n          Paint()\n            ..color = Colors.white.withValues(alpha: 0.75)\n            ..style = PaintingStyle.stroke\n            ..strokeWidth = r * 0.12\n            ..strokeCap = StrokeCap.round,\n        );\n\n        // Green citrus leaf on top\n        final Path leaf = Path()\n          ..moveTo(-r * 0.2, -r * 0.68)\n          ..quadraticBezierTo(-r * 0.05, -r * 1.25, r * 0.55, -r * 1.05)\n          ..quadraticBezierTo(r * 0.25, -r * 0.62, -r * 0.2, -r * 0.68)\n          ..close();\n        canvas.drawPath(leaf, Paint()..color = const Color(0xFF22C55E));\n        canvas.drawPath(leaf, outline);\n        canvas.restore();\n        break;\n\n      case LemonItemType.crosstopPill:\n        // \"[crosstops] Pill pop in peace\"\n        // Cartoon two-tone capsule + white scored crosstop tablet\n        canvas.save();\n        canvas.translate(c.dx - r * 0.18, c.dy - r * 0.12);\n        canvas.rotate(-0.55);\n        final RRect topHalf = RRect.fromRectAndCorners(\n          Rect.fromLTWH(-r * 0.42, -r * 0.78, r * 0.84, r * 0.78),\n          topLeft: Radius.circular(r * 0.42),\n          topRight: Radius.circular(r * 0.42),\n        );\n        final RRect bottomHalf = RRect.fromRectAndCorners(\n          Rect.fromLTWH(-r * 0.42, 0, r * 0.84, r * 0.78),\n          bottomLeft: Radius.circular(r * 0.42),\n          bottomRight: Radius.circular(r * 0.42),\n        );\n        canvas.drawRRect(topHalf, Paint()..color = const Color(0xFFEF4444));\n        canvas.drawRRect(bottomHalf, Paint()..color = Colors.white);\n        canvas.drawRRect(\n          RRect.fromRectAndRadius(\n            Rect.fromCenter(\n              center: Offset.zero,\n              width: r * 0.84,\n              height: r * 1.56,\n            ),\n            Radius.circular(r * 0.42),\n          ),\n          outline,\n        );\n        canvas.drawLine(\n          Offset(-r * 0.42, 0),\n          Offset(r * 0.42, 0),\n          outline,\n        );\n        canvas.restore();\n\n        // Foreground crosstop tablet with '+' score lines\n        final Offset tabCenter = c + Offset(r * 0.32, r * 0.28);\n        canvas.drawCircle(\n          tabCenter,\n          r * 0.52,\n          Paint()..color = const Color(0xFFF8FAFC),\n        );\n        canvas.drawCircle(tabCenter, r * 0.52, outline);\n        canvas.drawLine(\n          tabCenter + Offset(-r * 0.32, 0),\n          tabCenter + Offset(r * 0.32, 0),\n          outline,\n        );\n        canvas.drawLine(\n          tabCenter + Offset(0, -r * 0.32),\n          tabCenter + Offset(0, r * 0.32),\n          outline,\n        );\n        break;\n\n      case LemonItemType.elixirPotion:\n        // \"[elixir] A violent, greedy alchemist. Amethyst, channeling\"\n        // Bubbling amethyst potion flask with cork stopper\n        final Path cork = Path()\n          ..moveTo(c.dx - r * 0.22, c.dy - r * 0.78)\n          ..lineTo(c.dx - r * 0.28, c.dy - r * 1.05)\n          ..lineTo(c.dx + r * 0.28, c.dy - r * 1.05)\n          ..lineTo(c.dx + r * 0.22, c.dy - r * 0.78)\n          ..close();\n        canvas.drawPath(cork, Paint()..color = const Color(0xFFB45309));\n        canvas.drawPath(cork, outline);\n\n        // Glass neck\n        canvas.drawRect(\n          Rect.fromCenter(\n            center: c + Offset(0, -r * 0.62),\n            width: r * 0.46,\n            height: r * 0.36,\n          ),\n          Paint()..color = const Color(0xFFE0E7FF),\n        );\n        canvas.drawRect(\n          Rect.fromCenter(\n            center: c + Offset(0, -r * 0.62),\n            width: r * 0.46,\n            height: r * 0.36,\n          ),\n          outline,\n        );\n\n        // Bulbous flask body\n        final Offset bulbCenter = c + Offset(0, r * 0.16);\n        canvas.drawCircle(\n          bulbCenter,\n          r * 0.74,\n          Paint()..color = const Color(0xFFDDD6FE),\n        );\n        // Glowing purple elixir liquid inside\n        canvas.drawArc(\n          Rect.fromCircle(center: bulbCenter, radius: r * 0.65),\n          -0.2,\n          pi + 0.4,\n          true,\n          Paint()..color = const Color(0xFF9333EA),\n        );\n        // Magic bubbles\n        canvas.drawCircle(\n          bulbCenter + Offset(-r * 0.22, r * 0.12),\n          r * 0.12,\n          Paint()..color = const Color(0xFFF0ABFC),\n        );\n        canvas.drawCircle(\n          bulbCenter + Offset(r * 0.18, -r * 0.08),\n          r * 0.09,\n          Paint()..color = Colors.white,\n        );\n        canvas.drawCircle(bulbCenter, r * 0.74, outline);\n        break;\n\n      case LemonItemType.blueCandle:\n        // \"Blue candle wax drips onto bolded yellow letters\" / \"Mirtazipine and candlewax\"\n        final RRect candleBody = RRect.fromRectAndRadius(\n          Rect.fromCenter(\n            center: c + Offset(0, r * 0.24),\n            width: r * 0.92,\n            height: r * 1.18,\n          ),\n          Radius.circular(r * 0.16),\n        );\n        canvas.drawRRect(\n          candleBody,\n          Paint()..color = const Color(0xFF0284C7),\n        );\n        canvas.drawRRect(candleBody, outline);\n\n        // Dripping blue wax down the candle front\n        final Path waxDrips = Path()\n          ..moveTo(c.dx - r * 0.46, c.dy - r * 0.32)\n          ..quadraticBezierTo(\n            c.dx - r * 0.25,\n            c.dy + r * 0.22,\n            c.dx - r * 0.12,\n            c.dy - r * 0.15,\n          )\n          ..quadraticBezierTo(\n            c.dx + r * 0.08,\n            c.dy + r * 0.38,\n            c.dx + r * 0.22,\n            c.dy - r * 0.12,\n          )\n          ..quadraticBezierTo(\n            c.dx + r * 0.36,\n            c.dy + r * 0.12,\n            c.dx + r * 0.46,\n            c.dy - r * 0.32,\n          )\n          ..close();\n        canvas.drawPath(waxDrips, Paint()..color = const Color(0xFF7DD3FC));\n        canvas.drawPath(waxDrips, outline);\n\n        // Wick & Butane/Candle Flame\n        canvas.drawLine(\n          c + Offset(0, -r * 0.35),\n          c + Offset(0, -r * 0.52),\n          outline,\n        );\n        final Path outerFlame = Path()\n          ..moveTo(c.dx, c.dy - r * 1.08)\n          ..quadraticBezierTo(\n            c.dx + r * 0.38,\n            c.dy - r * 0.65,\n            c.dx,\n            c.dy - r * 0.48,\n          )\n          ..quadraticBezierTo(\n            c.dx - r * 0.38,\n            c.dy - r * 0.65,\n            c.dx,\n            c.dy - r * 1.08,\n          )\n          ..close();\n        canvas.drawPath(outerFlame, Paint()..color = const Color(0xFFF97316));\n        canvas.drawPath(outerFlame, outline);\n        canvas.drawCircle(\n          c + Offset(0, -r * 0.68),\n          r * 0.14,\n          Paint()..color = const Color(0xFFFEF08A),\n        );\n        break;\n\n      case LemonItemType.coffeeCup:\n        // \"10th cup of Colombian\" / \"drinking outta cups\"\n        // Cup handle\n        canvas.drawArc(\n          Rect.fromCenter(\n            center: c + Offset(r * 0.52, r * 0.12),\n            width: r * 0.62,\n            height: r * 0.68,\n          ),\n          -pi / 2,\n          pi,\n          false,\n          Paint()\n            ..color = Colors.white\n            ..style = PaintingStyle.stroke\n            ..strokeWidth = r * 0.18,\n        );\n        canvas.drawArc(\n          Rect.fromCenter(\n            center: c + Offset(r * 0.52, r * 0.12),\n            width: r * 0.62,\n            height: r * 0.68,\n          ),\n          -pi / 2,\n          pi,\n          false,\n          outline,\n        );\n\n        // Mug body\n        final RRect mug = RRect.fromRectAndCorners(\n          Rect.fromCenter(\n            center: c + Offset(-r * 0.08, r * 0.16),\n            width: r * 1.15,\n            height: r * 1.08,\n          ),\n          bottomLeft: Radius.circular(r * 0.45),\n          bottomRight: Radius.circular(r * 0.45),\n          topLeft: Radius.circular(r * 0.1),\n          topRight: Radius.circular(r * 0.1),\n        );\n        canvas.drawRRect(mug, Paint()..color = const Color(0xFFFFFBEB));\n        canvas.drawRRect(mug, outline);\n\n        // Dark Colombian coffee surface\n        canvas.drawOval(\n          Rect.fromCenter(\n            center: c + Offset(-r * 0.08, -r * 0.34),\n            width: r * 1.12,\n            height: r * 0.34,\n          ),\n          Paint()..color = const Color(0xFF451A03),\n        );\n        canvas.drawOval(\n          Rect.fromCenter(\n            center: c + Offset(-r * 0.08, -r * 0.34),\n            width: r * 1.12,\n            height: r * 0.34,\n          ),\n          outline,\n        );\n\n        // Rising steam curls\n        final Paint steamPaint = Paint()\n          ..color = Colors.white.withValues(alpha: 0.85)\n          ..style = PaintingStyle.stroke\n          ..strokeWidth = r * 0.1\n          ..strokeCap = StrokeCap.round;\n        for (int s = -1; s <= 1; s += 2) {\n          final double sx = c.dx - r * 0.08 + s * r * 0.24;\n          final Path steam = Path()\n            ..moveTo(sx, c.dy - r * 0.55)\n            ..quadraticBezierTo(\n              sx + s * r * 0.14,\n              c.dy - r * 0.78,\n              sx - s * r * 0.06,\n              c.dy - r * 0.98,\n            );\n          canvas.drawPath(steam, steamPaint);\n        }\n        break;\n\n      case LemonItemType.cherrySeven:\n        // \"The sevens are repetitive. Cherry on top of cherry-flavored sedatives.\"\n        final Offset leftCherry = c + Offset(-r * 0.42, r * 0.38);\n        final Offset rightCherry = c + Offset(r * 0.42, r * 0.38);\n        final Offset stemTop = c + Offset(0, -r * 0.88);\n\n        // Green arched cherry stems\n        final Path stems = Path()\n          ..moveTo(leftCherry.dx, leftCherry.dy - r * 0.2)\n          ..quadraticBezierTo(\n            c.dx - r * 0.35,\n            c.dy - r * 0.45,\n            stemTop.dx,\n            stemTop.dy,\n          )\n          ..quadraticBezierTo(\n            c.dx + r * 0.35,\n            c.dy - r * 0.45,\n            rightCherry.dx,\n            rightCherry.dy - r * 0.2,\n          );\n        canvas.drawPath(\n          stems,\n          Paint()\n            ..color = const Color(0xFF16A34A)\n            ..style = PaintingStyle.stroke\n            ..strokeWidth = r * 0.14\n            ..strokeCap = StrokeCap.round,\n        );\n\n        // Twin glossy cartoon cherries\n        for (final pos in [leftCherry, rightCherry]) {\n          canvas.drawCircle(\n            pos,\n            r * 0.44,\n            Paint()..color = const Color(0xFFE11D48),\n          );\n          canvas.drawCircle(pos, r * 0.44, outline);\n          canvas.drawCircle(\n            pos + Offset(-r * 0.14, -r * 0.14),\n            r * 0.12,\n            Paint()..color = Colors.white.withValues(alpha: 0.85),\n          );\n        }\n\n        // Golden Lucky '7' badge in the center\n        final TextPainter sevenTp = TextPainter(\n          text: TextSpan(\n            text: '7',\n            style: TextStyle(\n              color: const Color(0xFFFACC15),\n              fontFamily: 'JetBrainsMono',\n              fontWeight: FontWeight.w900,\n              fontSize: r * 1.05,\n              shadows: const [\n                Shadow(\n                  color: Color(0xFF0F172A),\n                  offset: Offset(1.5, 1.5),\n                  blurRadius: 1,\n                ),\n              ],\n            ),\n          ),\n          textDirection: TextDirection.ltr,\n        )..layout();\n        sevenTp.paint(\n          canvas,\n          c - Offset(sevenTp.width / 2, sevenTp.height * 0.72),\n        );\n        break;\n    }\n  }\n\n  @override\n  bool shouldRepaint(covariant _LemonItemPainter oldDelegate) =>\n      oldDelegate.type != type;\n}\n",
  "lib/games/santa_game.dart": "import 'dart:async';\nimport 'dart:math';\nimport 'package:archbtw_sh/global/site_music_controller.dart';\nimport 'package:archbtw_sh/widgets/in_game_music_hud.dart';\nimport 'package:audioplayers/audioplayers.dart';\nimport 'package:flutter/material.dart';\nimport 'package:flutter/scheduler.dart';\nimport 'package:flutter/services.dart';\n\nconst Color kCrimsonRed = Color(0xFFD90429);\nconst Color kDarkBlood = Color(0xFF780000);\nconst Color kNoseGlow = Color(0xFFFF1E42);\nconst Color kSnowWhite = Color(0xFFF0F4F8);\nconst Color kSnowShadow = Color(0xFFBCCCDC);\nconst Color kNightTop = Color(0xFF050814);\nconst Color kNightBottom = Color(0xFF101B38);\n\nconst List<String> kReindeerNames = [\n  'DASHER',\n  'DANCER',\n  'PRANCER',\n  'VIXEN',\n  'COMET',\n  'CUPID',\n  'DONNER',\n  'BLITZEN',\n];\n\nclass SantasInvadersGame extends StatefulWidget {\n  const SantasInvadersGame({super.key});\n\n  @override\n  State<SantasInvadersGame> createState() => _SantasInvadersGameState();\n}\n\nclass _SantasInvadersGameState extends State<SantasInvadersGame>\n    with SingleTickerProviderStateMixin {\n  final FocusNode _focusNode = FocusNode();\n  final AudioPlayer _audioPlayer = AudioPlayer();\n  final Random _rng = Random();\n\n  late Ticker _ticker;\n  Duration _lastElapsed = Duration.zero;\n  double _worldTime = 0.0;\n\n  // Normalized world coordinates:\n  // X: 0.0 (left) to 1.0 (right)\n  // Y: 0.0 (top) to 1.0 (bottom), ground is at Y = 0.80\n  static const double _groundY = 0.80;\n  static const double _gravity = 1.95;\n\n  // Platforms (xMin, xMax, y)\n  final List<_Platform> _platforms = const [\n    _Platform(xMin: 0.08, xMax: 0.34, y: 0.63),\n    _Platform(xMin: 0.66, xMax: 0.92, y: 0.63),\n    _Platform(xMin: 0.32, xMax: 0.68, y: 0.47),\n  ];\n\n  // Rudolph state\n  double _playerX = 0.22;\n  double _playerY = _groundY;\n  double _playerVy = 0.0;\n  bool _facingRight = true;\n  double _aimAngle = 0.0; // radians, 0 = right, pi = left, -pi/2 = up\n  bool _isGrounded = true;\n  int _jumpsRemaining = 2;\n  double _walkCycle = 0.0;\n  double _muzzleFlashTimer = 0.0;\n  double _fireCooldown = 0.0;\n  double _recoilOffset = 0.0;\n\n  // Input states (Keyboard)\n  final Set<LogicalKeyboardKey> _keysPressed = {};\n  bool _mouseShooting = false;\n\n  // Input states (Touch Joystick & Buttons)\n  int? _joystickPointerId;\n  Offset _joystickCenter = Offset.zero;\n  Offset _joystickDelta = Offset.zero; // normalized -1..1\n  int? _shootButtonPointerId;\n  int? _jumpButtonPointerId;\n\n  // Game stats\n  int _score = 0;\n  int _kills = 0;\n  int _combo = 0;\n  double _comboTimer = 0.0;\n\n  // Entities\n  final List<_Bullet> _bullets = [];\n  final List<_ReindeerTarget> _reindeer = [];\n  final List<_BloodParticle> _bloodParticles = [];\n  final List<_SnowStain> _snowStains = [];\n  final List<_ShellCasing> _shells = [];\n  final List<_FloatingText> _floatingTexts = [];\n  final List<_HorizonCross> _horizonCrosses = [];\n  late final List<_Snowflake> _snowflakes;\n  late final List<_Star> _stars;\n\n  double _spawnTimer = 0.0;\n\n  // Audio playlist (Santa's Cookies EP)\n  final List<String> _playlist = [\n    'rudolph_spoke_in_class_today.m4a',\n    'who_you_calling_a_ho_ho.m4a',\n    'oh_christmas_tree.m4a',\n    'must_be_a_south_pole_elf.m4a',\n  ];\n  int _currentTrackIndex = 0;\n  bool _isMusicPlaying = true;\n  StreamSubscription? _playerCompleteSubscription;\n  StreamSubscription? _playerStateSubscription;\n\n  @override\n  void initState() {\n    super.initState();\n\n    _snowflakes = List.generate(\n      70,\n      (_) => _Snowflake(\n        x: _rng.nextDouble(),\n        y: _rng.nextDouble(),\n        radius: 1.2 + _rng.nextDouble() * 2.5,\n        speedY: 0.04 + _rng.nextDouble() * 0.08,\n        drift: (_rng.nextDouble() - 0.5) * 0.03,\n        phase: _rng.nextDouble() * pi * 2,\n      ),\n    );\n\n    _stars = List.generate(\n      45,\n      (_) => _Star(\n        x: _rng.nextDouble(),\n        y: _rng.nextDouble() * 0.52,\n        size: 0.8 + _rng.nextDouble() * 1.8,\n        twinklePhase: _rng.nextDouble() * pi * 2,\n      ),\n    );\n\n    _seedInitialReindeer();\n\n    _ticker = createTicker(_onTick)..start();\n\n    WidgetsBinding.instance.addPostFrameCallback((_) {\n      if (mounted) {\n        _focusNode.requestFocus();\n      }\n    });\n\n    _setupAudioPlayer();\n  }\n\n  @override\n  void dispose() {\n    SiteMusicController.instance.exitGame();\n    _ticker.dispose();\n    _focusNode.dispose();\n    _playerCompleteSubscription?.cancel();\n    _playerStateSubscription?.cancel();\n    _audioPlayer.dispose();\n    super.dispose();\n  }\n\n  void _setupAudioPlayer() {\n    SiteMusicController.instance.enterGame();\n    configureBackgroundAudioContext();\n    _audioPlayer.setReleaseMode(ReleaseMode.release);\n    _playerCompleteSubscription = _audioPlayer.onPlayerComplete.listen((_) {\n      _playNextTrack();\n    });\n    _playerStateSubscription = _audioPlayer.onPlayerStateChanged.listen((state) {\n      if (mounted) {\n        setState(() {\n          _isMusicPlaying = state == PlayerState.playing;\n        });\n      }\n    });\n    _playTrackAt(0);\n  }\n\n  Future<void> _playTrackAt(int index) async {\n    if (_playlist.isEmpty) return;\n    final int wrapped = (index % _playlist.length + _playlist.length) % _playlist.length;\n    if (mounted) {\n      setState(() {\n        _currentTrackIndex = wrapped;\n        _isMusicPlaying = true;\n      });\n    }\n    final nextSong = _playlist[wrapped];\n    try {\n      await _audioPlayer.setSource(AssetSource('music/santas_cookies/\$nextSong'));\n      await _audioPlayer.setVolume(0.5);\n      await _audioPlayer.resume();\n    } catch (e) {\n      debugPrint('Audio Error: \$e');\n    }\n  }\n\n  Future<void> _playNextTrack() async {\n    await _playTrackAt(_currentTrackIndex + 1);\n  }\n\n  Future<void> _playPreviousTrack() async {\n    await _playTrackAt(_currentTrackIndex - 1);\n  }\n\n  Future<void> _togglePlayPause() async {\n    try {\n      if (_isMusicPlaying) {\n        await _audioPlayer.pause();\n        if (mounted) setState(() => _isMusicPlaying = false);\n      } else {\n        await _audioPlayer.resume();\n        if (mounted) setState(() => _isMusicPlaying = true);\n      }\n    } catch (e) {\n      debugPrint('Audio Toggle Error: \$e');\n    }\n  }\n\n  void _seedInitialReindeer() {\n    _reindeer.clear();\n    for (int i = 0; i < 5; i++) {\n      _spawnReindeer(initialSpread: true);\n    }\n  }\n\n  void _resetAll() {\n    setState(() {\n      _score = 0;\n      _kills = 0;\n      _combo = 0;\n      _comboTimer = 0.0;\n      _playerX = 0.22;\n      _playerY = _groundY;\n      _playerVy = 0.0;\n      _facingRight = true;\n      _bullets.clear();\n      _bloodParticles.clear();\n      _snowStains.clear();\n      _shells.clear();\n      _floatingTexts.clear();\n      _horizonCrosses.clear();\n      _seedInitialReindeer();\n    });\n  }\n\n  void _spawnReindeer({bool initialSpread = false}) {\n    if (_reindeer.length >= 9) return;\n\n    final name = kReindeerNames[_rng.nextInt(kReindeerNames.length)];\n    final bool isPrancingSky = _rng.nextDouble() < 0.22;\n    final bool fromLeft = _rng.nextBool();\n\n    double startX;\n    if (initialSpread) {\n      startX = 0.38 + _rng.nextDouble() * 0.55;\n    } else {\n      startX = fromLeft ? -0.06 : 1.06;\n    }\n\n    double targetY = _groundY;\n    if (isPrancingSky) {\n      targetY = 0.20 + _rng.nextDouble() * 0.22;\n    } else if (_rng.nextDouble() < 0.45) {\n      final p = _platforms[_rng.nextInt(_platforms.length)];\n      targetY = p.y;\n      if (initialSpread) {\n        startX = p.xMin + _rng.nextDouble() * (p.xMax - p.xMin);\n      }\n    }\n\n    final double baseSpeed = 0.055 + _rng.nextDouble() * 0.065;\n    final double dir = initialSpread\n        ? (_rng.nextBool() ? 1.0 : -1.0)\n        : (fromLeft ? 1.0 : -1.0);\n\n    _reindeer.add(\n      _ReindeerTarget(\n        name: name,\n        x: startX,\n        y: targetY,\n        vx: dir * baseSpeed,\n        vy: 0.0,\n        isFlying: isPrancingSky,\n        hp: 3,\n        maxHp: 3,\n        furVariant: _rng.nextInt(3),\n        legPhase: _rng.nextDouble() * pi * 2,\n      ),\n    );\n  }\n\n  KeyEventResult _handleKeyEvent(FocusNode node, KeyEvent event) {\n    if (event is KeyDownEvent) {\n      _keysPressed.add(event.logicalKey);\n      if (event.logicalKey == LogicalKeyboardKey.space ||\n          event.logicalKey == LogicalKeyboardKey.keyZ ||\n          event.logicalKey == LogicalKeyboardKey.keyK) {\n        _triggerJump();\n      }\n    } else if (event is KeyUpEvent) {\n      _keysPressed.remove(event.logicalKey);\n    }\n    return KeyEventResult.handled;\n  }\n\n  void _triggerJump() {\n    final bool holdingDown =\n        _keysPressed.contains(LogicalKeyboardKey.keyS) ||\n        _keysPressed.contains(LogicalKeyboardKey.arrowDown) ||\n        _joystickDelta.dy > 0.55;\n\n    // Drop through platform if holding down on an elevated platform\n    if (holdingDown && _isGrounded && _playerY < _groundY - 0.02) {\n      setState(() {\n        _playerY += 0.03;\n        _isGrounded = false;\n      });\n      return;\n    }\n\n    if (_jumpsRemaining > 0) {\n      setState(() {\n        _playerVy = -0.78;\n        _isGrounded = false;\n        _jumpsRemaining--;\n      });\n      HapticFeedback.lightImpact();\n    }\n  }\n\n  void _fireWeapon() {\n    if (_fireCooldown > 0) return;\n    _fireCooldown = 0.11; // rapid fire Contra rifle\n    _muzzleFlashTimer = 0.06;\n    _recoilOffset = 0.012;\n\n    // Gun barrel tip position in normalized coordinates\n    final double cosA = cos(_aimAngle);\n    final double sinA = sin(_aimAngle);\n    final double muzzleX = _playerX + cosA * 0.038;\n    final double muzzleY = (_playerY - 0.055) + sinA * 0.038;\n\n    // Slight spread for rapid machine-gun feel\n    final double spread = (_rng.nextDouble() - 0.5) * 0.06;\n    final double shotAngle = _aimAngle + spread;\n    const double bulletSpeed = 1.35;\n\n    _bullets.add(\n      _Bullet(\n        x: muzzleX,\n        y: muzzleY,\n        vx: cos(shotAngle) * bulletSpeed,\n        vy: sin(shotAngle) * bulletSpeed,\n      ),\n    );\n\n    // Eject brass shell casing\n    _shells.add(\n      _ShellCasing(\n        x: _playerX,\n        y: _playerY - 0.06,\n        vx: (_facingRight ? -1 : 1) * (0.08 + _rng.nextDouble() * 0.08),\n        vy: -0.25 - _rng.nextDouble() * 0.12,\n        rotation: _rng.nextDouble() * pi,\n      ),\n    );\n    if (_shells.length > 35) {\n      _shells.removeAt(0);\n    }\n\n    // Scare nearby reindeer when gunfire rings out\n    for (final r in _reindeer) {\n      if ((r.x - _playerX).abs() < 0.45) {\n        r.panicTimer = 2.0;\n      }\n    }\n  }\n\n  void _onTick(Duration elapsed) {\n    final double dt = _lastElapsed == Duration.zero\n        ? 0.016\n        : ((elapsed - _lastElapsed).inMicroseconds / 1000000.0).clamp(\n            0.001,\n            0.05,\n          );\n    _lastElapsed = elapsed;\n\n    setState(() {\n      _worldTime += dt;\n      if (_muzzleFlashTimer > 0) _muzzleFlashTimer = max(0, _muzzleFlashTimer - dt);\n      if (_fireCooldown > 0) _fireCooldown = max(0, _fireCooldown - dt);\n      if (_recoilOffset > 0) _recoilOffset = max(0, _recoilOffset - dt * 0.09);\n\n      if (_comboTimer > 0) {\n        _comboTimer -= dt;\n        if (_comboTimer <= 0) {\n          _combo = 0;\n        }\n      }\n\n      _updatePlayer(dt);\n      _updateBulletsAndCollisions(dt);\n      _updateReindeer(dt);\n      _updateParticles(dt);\n      _updateSnowflakes(dt);\n\n      _spawnTimer -= dt;\n      if (_spawnTimer <= 0) {\n        _spawnReindeer();\n        _spawnTimer = _reindeer.length < 4 ? 0.55 : 1.15;\n      }\n    });\n  }\n\n  void _updatePlayer(double dt) {\n    // Combine keyboard and virtual joystick input\n    double moveX = 0.0;\n    double aimX = 0.0;\n    double aimY = 0.0;\n\n    if (_keysPressed.contains(LogicalKeyboardKey.keyA) ||\n        _keysPressed.contains(LogicalKeyboardKey.arrowLeft)) {\n      moveX -= 1.0;\n      aimX -= 1.0;\n    }\n    if (_keysPressed.contains(LogicalKeyboardKey.keyD) ||\n        _keysPressed.contains(LogicalKeyboardKey.arrowRight)) {\n      moveX += 1.0;\n      aimX += 1.0;\n    }\n    if (_keysPressed.contains(LogicalKeyboardKey.keyW) ||\n        _keysPressed.contains(LogicalKeyboardKey.arrowUp)) {\n      aimY -= 1.0;\n    }\n    if (_keysPressed.contains(LogicalKeyboardKey.keyS) ||\n        _keysPressed.contains(LogicalKeyboardKey.arrowDown)) {\n      aimY += 1.0;\n    }\n\n    if (_joystickPointerId != null && _joystickDelta.distance > 0.14) {\n      if (_joystickDelta.dx.abs() > 0.22) {\n        moveX = _joystickDelta.dx.clamp(-1.0, 1.0);\n      }\n      aimX = _joystickDelta.dx;\n      aimY = _joystickDelta.dy;\n    }\n\n    if (moveX < -0.05) _facingRight = false;\n    if (moveX > 0.05) _facingRight = true;\n\n    // 8-way Contra snapping for aim\n    if (aimX.abs() > 0.15 || aimY.abs() > 0.15) {\n      // Prevent aiming straight down when standing on ground\n      if (_isGrounded && aimY > 0.4 && aimX.abs() < 0.35) {\n        _aimAngle = _facingRight ? 0.0 : pi;\n      } else {\n        final double rawAngle = atan2(aimY, aimX);\n        // Snap to 8 directions (multiples of pi / 4)\n        final double step = pi / 4;\n        _aimAngle = (rawAngle / step).round() * step;\n      }\n    } else {\n      _aimAngle = _facingRight ? 0.0 : pi;\n    }\n\n    // Horizontal movement\n    const double playerSpeed = 0.36;\n    _playerX += moveX * playerSpeed * dt;\n    _playerX = _playerX.clamp(0.05, 0.95);\n\n    if (moveX.abs() > 0.05 && _isGrounded) {\n      _walkCycle += dt * 14.0;\n    } else if (_isGrounded) {\n      _walkCycle = 0.0;\n    }\n\n    // Vertical movement & platform collisions\n    final double prevY = _playerY;\n    _playerVy += _gravity * dt;\n    _playerY += _playerVy * dt;\n    _isGrounded = false;\n\n    // Check landing on elevated platforms when falling\n    if (_playerVy >= 0) {\n      for (final p in _platforms) {\n        if (_playerX >= p.xMin &&\n            _playerX <= p.xMax &&\n            prevY <= p.y + 0.008 &&\n            _playerY >= p.y) {\n          _playerY = p.y;\n          _playerVy = 0.0;\n          _isGrounded = true;\n          _jumpsRemaining = 2;\n          break;\n        }\n      }\n    }\n\n    // Ground collision\n    if (_playerY >= _groundY) {\n      _playerY = _groundY;\n      _playerVy = 0.0;\n      _isGrounded = true;\n      _jumpsRemaining = 2;\n    }\n\n    // Check shooting input (Keyboard or Touch Shoot button or Mouse hold)\n    final bool wantsShoot =\n        _shootButtonPointerId != null ||\n        _mouseShooting ||\n        _keysPressed.contains(LogicalKeyboardKey.keyJ) ||\n        _keysPressed.contains(LogicalKeyboardKey.keyX) ||\n        _keysPressed.contains(LogicalKeyboardKey.keyF) ||\n        _keysPressed.contains(LogicalKeyboardKey.enter) ||\n        _keysPressed.contains(LogicalKeyboardKey.shiftLeft) ||\n        _keysPressed.contains(LogicalKeyboardKey.shiftRight);\n\n    if (wantsShoot) {\n      _fireWeapon();\n    }\n  }\n\n  void _updateBulletsAndCollisions(double dt) {\n    final List<_Bullet> bulletsToRemove = [];\n    final List<_ReindeerTarget> killedReindeer = [];\n\n    for (final b in _bullets) {\n      b.x += b.vx * dt;\n      b.y += b.vy * dt;\n\n      if (b.x < -0.05 || b.x > 1.05 || b.y < -0.05 || b.y > 1.0) {\n        bulletsToRemove.add(b);\n        continue;\n      }\n\n      // Check collision with any reindeer (they have no weapons and cannot hurt Rudolph)\n      for (final r in _reindeer) {\n        if (r.hp <= 0) continue;\n        final double hitCenterX = r.x;\n        final double hitCenterY = r.y - 0.042;\n        final double dx = b.x - hitCenterX;\n        final double dy = b.y - hitCenterY;\n\n        if (dx.abs() < 0.046 && dy.abs() < 0.048) {\n          bulletsToRemove.add(b);\n          r.hp--;\n          r.hitFlash = 0.18;\n          r.panicTimer = 3.0;\n          // Boost fleeing speed when shot\n          if (r.vx.abs() < 0.14) {\n            final double fleeDir = (r.x >= _playerX) ? 1.0 : -1.0;\n            r.vx = fleeDir * (0.14 + _rng.nextDouble() * 0.05);\n          }\n\n          _score += 100;\n          _spawnBloodBurst(\n            x: b.x,\n            y: b.y,\n            count: r.hp <= 0 ? 38 : 14,\n            bulletVx: b.vx,\n            bulletVy: b.vy,\n            isFatal: r.hp <= 0,\n          );\n\n          if (r.hp <= 0) {\n            killedReindeer.add(r);\n            _onReindeerKilled(r);\n          } else {\n            _floatingTexts.add(\n              _FloatingText(\n                text: '+100',\n                x: r.x,\n                y: r.y - 0.08,\n                color: Colors.white,\n                life: 0.65,\n              ),\n            );\n          }\n          break;\n        }\n      }\n    }\n\n    _bullets.removeWhere((b) => bulletsToRemove.contains(b));\n    _reindeer.removeWhere((r) => killedReindeer.contains(r));\n  }\n\n  void _onReindeerKilled(_ReindeerTarget r) {\n    _kills++;\n    _combo++;\n    _comboTimer = 3.2;\n\n    final int killBonus = 500 * _combo;\n    _score += killBonus;\n\n    _floatingTexts.add(\n      _FloatingText(\n        text: '✖ \${r.name} +\$killBonus',\n        x: r.x.clamp(0.1, 0.9),\n        y: r.y - 0.09,\n        color: kCrimsonRed,\n        life: 1.25,\n        isBold: true,\n      ),\n    );\n\n    // Add a blood stain directly below if near ground/platform\n    _addSnowStainAt(r.x, r.isFlying ? _groundY : r.y, radius: 0.038);\n\n    // Add a little cross on the distant snow ridge (\"The next day, the crosses lined the horizon\")\n    if (_horizonCrosses.length < 24) {\n      _horizonCrosses.add(\n        _HorizonCross(\n          x: (0.08 + (_kills * 0.073 + _rng.nextDouble() * 0.03) % 0.84),\n          tilt: (_rng.nextDouble() - 0.5) * 0.18,\n        ),\n      );\n    }\n\n    HapticFeedback.mediumImpact();\n  }\n\n  void _spawnBloodBurst({\n    required double x,\n    required double y,\n    required int count,\n    required double bulletVx,\n    required double bulletVy,\n    required bool isFatal,\n  }) {\n    for (int i = 0; i < count; i++) {\n      final double angle = _rng.nextDouble() * pi * 2;\n      final double speed = 0.06 + _rng.nextDouble() * (isFatal ? 0.42 : 0.24);\n      _bloodParticles.add(\n        _BloodParticle(\n          x: x,\n          y: y,\n          vx: cos(angle) * speed + bulletVx * 0.12,\n          vy: sin(angle) * speed - 0.14 + bulletVy * 0.08,\n          radius: isFatal\n              ? (2.2 + _rng.nextDouble() * 4.5)\n              : (1.8 + _rng.nextDouble() * 3.0),\n          life: 0.55 + _rng.nextDouble() * 0.55,\n          isChunk: isFatal && i < 5,\n        ),\n      );\n    }\n  }\n\n  void _addSnowStainAt(double x, double y, {double radius = 0.022}) {\n    _snowStains.add(\n      _SnowStain(\n        x: x.clamp(0.02, 0.98),\n        y: y,\n        radiusX: radius * (0.8 + _rng.nextDouble() * 0.6),\n        radiusY: radius * 0.32,\n      ),\n    );\n    if (_snowStains.length > 70) {\n      _snowStains.removeAt(0);\n    }\n  }\n\n  void _updateReindeer(double dt) {\n    for (final r in _reindeer) {\n      if (r.hitFlash > 0) r.hitFlash = max(0, r.hitFlash - dt);\n      if (r.panicTimer > 0) r.panicTimer = max(0, r.panicTimer - dt);\n\n      final double speedMult = r.panicTimer > 0 ? 1.55 : 1.0;\n      r.x += r.vx * speedMult * dt;\n      r.legPhase += dt * (r.panicTimer > 0 ? 16.0 : 9.5);\n\n      if (r.isFlying) {\n        // Prancing wave motion in the night sky\n        r.y += sin(_worldTime * 3.5 + r.legPhase * 0.2) * 0.04 * dt;\n      } else {\n        // Occasional joyful/panicked hop\n        if (r.vy == 0 && _rng.nextDouble() < (r.panicTimer > 0 ? 0.03 : 0.008)) {\n          r.vy = -0.36;\n        }\n        if (r.vy != 0 || r.y < r.baseY) {\n          r.vy += _gravity * 0.75 * dt;\n          r.y += r.vy * dt;\n          if (r.y >= r.baseY) {\n            r.y = r.baseY;\n            r.vy = 0.0;\n          }\n        }\n      }\n\n      // Keep on platform or turn around at edges\n      if (!r.isFlying && r.baseY < _groundY - 0.02) {\n        final platform = _platforms.firstWhere(\n          (p) => (p.y - r.baseY).abs() < 0.03,\n          orElse: () => const _Platform(xMin: 0.05, xMax: 0.95, y: _groundY),\n        );\n        if (r.x < platform.xMin + 0.02) {\n          r.x = platform.xMin + 0.02;\n          r.vx = r.vx.abs();\n        } else if (r.x > platform.xMax - 0.02) {\n          r.x = platform.xMax - 0.02;\n          r.vx = -r.vx.abs();\n        }\n      } else {\n        // Wrap or bounce at screen edges\n        if (r.x < -0.08 && r.vx < 0) {\n          r.vx = r.vx.abs();\n        } else if (r.x > 1.08 && r.vx > 0) {\n          r.vx = -r.vx.abs();\n        }\n      }\n    }\n  }\n\n  void _updateParticles(double dt) {\n    for (final p in _bloodParticles) {\n      final double prevY = p.y;\n      p.x += p.vx * dt;\n      p.vy += _gravity * 0.85 * dt;\n      p.y += p.vy * dt;\n      p.life -= dt;\n\n      // Check if blood droplet hits a platform or the snow ground\n      for (final plat in _platforms) {\n        if (p.vy > 0 &&\n            p.x >= plat.xMin &&\n            p.x <= plat.xMax &&\n            prevY <= plat.y &&\n            p.y >= plat.y) {\n          _addSnowStainAt(p.x, plat.y, radius: 0.015);\n          p.life = 0;\n          break;\n        }\n      }\n      if (p.y >= _groundY && p.life > 0) {\n        _addSnowStainAt(p.x, _groundY, radius: 0.018);\n        p.life = 0;\n      }\n    }\n    _bloodParticles.removeWhere((p) => p.life <= 0);\n\n    for (final s in _shells) {\n      s.x += s.vx * dt;\n      s.vy += _gravity * dt;\n      s.y += s.vy * dt;\n      s.rotation += dt * 10.0;\n      if (s.y >= _groundY) {\n        s.y = _groundY;\n        s.vx *= 0.4;\n        s.vy = 0;\n      }\n    }\n\n    for (final ft in _floatingTexts) {\n      ft.y -= 0.065 * dt;\n      ft.life -= dt;\n    }\n    _floatingTexts.removeWhere((ft) => ft.life <= 0);\n  }\n\n  void _updateSnowflakes(double dt) {\n    for (final flake in _snowflakes) {\n      flake.y += flake.speedY * dt;\n      flake.x += (flake.drift + sin(_worldTime + flake.phase) * 0.01) * dt;\n      if (flake.y > 1.0) {\n        flake.y = -0.02;\n        flake.x = _rng.nextDouble();\n      }\n      if (flake.x < 0) flake.x += 1.0;\n      if (flake.x > 1.0) flake.x -= 1.0;\n    }\n  }\n\n  void _updateJoystickVector(Offset localPos, double maxRadius) {\n    final Offset raw = localPos - _joystickCenter;\n    final double dist = raw.distance;\n    if (dist <= 0.001) {\n      _joystickDelta = Offset.zero;\n      return;\n    }\n    final double clampedDist = min(dist, maxRadius);\n    final Offset dir = raw / dist;\n    _joystickDelta = dir * (clampedDist / maxRadius);\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      backgroundColor: kNightTop,\n      appBar: AppBar(\n        backgroundColor: const Color(0xFF060B19),\n        elevation: 0,\n        leading: const BackButton(color: Colors.white),\n        title: const Text(\n          'rudolph_spoke.sh',\n          style: TextStyle(\n            color: Colors.white,\n            fontFamily: 'JetBrainsMono',\n            fontSize: 15,\n            fontWeight: FontWeight.bold,\n          ),\n        ),\n        centerTitle: true,\n        actions: [\n          IconButton(\n            tooltip: 'Reset Snowfield',\n            onPressed: _resetAll,\n            icon: const Icon(Icons.refresh, color: Colors.white70, size: 20),\n          ),\n        ],\n        bottom: PreferredSize(\n          preferredSize: const Size.fromHeight(36),\n          child: InGameMusicHud(\n            currentTrack: _playlist[_currentTrackIndex],\n            isPlaying: _isMusicPlaying,\n            accentColor: kCrimsonRed,\n            onPrevious: _playPreviousTrack,\n            onPlayPause: _togglePlayPause,\n            onNext: _playNextTrack,\n          ),\n        ),\n      ),\n      body: KeyboardListener(\n        focusNode: _focusNode,\n        autofocus: true,\n        onKeyEvent: (event) => _handleKeyEvent(_focusNode, event),\n        child: LayoutBuilder(\n          builder: (context, constraints) {\n            final bool isCompact = constraints.maxWidth < 700;\n            final double joystickSize = isCompact ? 118.0 : 128.0;\n            final double joystickRadius = joystickSize / 2;\n\n            return Stack(\n              fit: StackFit.expand,\n              children: [\n                // Main Cartoon Game Canvas (supports click/hold to aim & shoot on desktop)\n                Listener(\n                  behavior: HitTestBehavior.opaque,\n                  onPointerDown: (event) {\n                    _focusNode.requestFocus();\n                    // Allow clicking/tapping canvas outside controls to aim & shoot\n                    final double normX = event.localPosition.dx / constraints.maxWidth;\n                    final double normY = event.localPosition.dy / constraints.maxHeight;\n                    if (normY < 0.75) {\n                      _facingRight = normX >= _playerX;\n                      _aimAngle = atan2(\n                        normY - (_playerY - 0.055),\n                        normX - _playerX,\n                      );\n                      _mouseShooting = true;\n                      _fireWeapon();\n                    }\n                  },\n                  onPointerMove: (event) {\n                    if (_mouseShooting) {\n                      final double normX =\n                          event.localPosition.dx / constraints.maxWidth;\n                      final double normY =\n                          event.localPosition.dy / constraints.maxHeight;\n                      _facingRight = normX >= _playerX;\n                      _aimAngle = atan2(\n                        normY - (_playerY - 0.055),\n                        normX - _playerX,\n                      );\n                    }\n                  },\n                  onPointerUp: (_) => _mouseShooting = false,\n                  onPointerCancel: (_) => _mouseShooting = false,\n                  child: CustomPaint(\n                    painter: _RudolphContraPainter(\n                      worldTime: _worldTime,\n                      playerX: _playerX,\n                      playerY: _playerY,\n                      facingRight: _facingRight,\n                      aimAngle: _aimAngle,\n                      walkCycle: _walkCycle,\n                      isGrounded: _isGrounded,\n                      muzzleFlashTimer: _muzzleFlashTimer,\n                      recoilOffset: _recoilOffset,\n                      kills: _kills,\n                      platforms: _platforms,\n                      bullets: _bullets,\n                      reindeer: _reindeer,\n                      bloodParticles: _bloodParticles,\n                      snowStains: _snowStains,\n                      shells: _shells,\n                      floatingTexts: _floatingTexts,\n                      horizonCrosses: _horizonCrosses,\n                      snowflakes: _snowflakes,\n                      stars: _stars,\n                    ),\n                  ),\n                ),\n\n                // Top HUD: Score & Crimson Checkmarks\n                Positioned(\n                  top: 10,\n                  left: 14,\n                  right: 14,\n                  child: IgnorePointer(\n                    child: Column(\n                      crossAxisAlignment: CrossAxisAlignment.stretch,\n                      children: [\n                        Wrap(\n                          alignment: WrapAlignment.spaceBetween,\n                          crossAxisAlignment: WrapCrossAlignment.center,\n                          spacing: 8,\n                          runSpacing: 6,\n                          children: [\n                            Container(\n                              padding: const EdgeInsets.symmetric(\n                                horizontal: 12,\n                                vertical: 8,\n                              ),\n                              decoration: BoxDecoration(\n                                color: Colors.black.withValues(alpha: 0.65),\n                                border: Border.all(\n                                  color: kCrimsonRed.withValues(alpha: 0.8),\n                                  width: 1.5,\n                                ),\n                                borderRadius: BorderRadius.circular(6),\n                              ),\n                              child: Column(\n                                crossAxisAlignment: CrossAxisAlignment.start,\n                                mainAxisSize: MainAxisSize.min,\n                                children: [\n                                  Text(\n                                    'POINTS: \$_score',\n                                    style: const TextStyle(\n                                      color: Colors.white,\n                                      fontFamily: 'JetBrainsMono',\n                                      fontWeight: FontWeight.bold,\n                                      fontSize: 16,\n                                    ),\n                                  ),\n                                  const SizedBox(height: 2),\n                                  Text(\n                                    'MARKED IN CRIMSON: \$_kills\${_combo > 1 ? \"  (\${_combo}x COMBO!)\" : \"\"}',\n                                    style: const TextStyle(\n                                      color: kCrimsonRed,\n                                      fontFamily: 'JetBrainsMono',\n                                      fontWeight: FontWeight.bold,\n                                      fontSize: 12,\n                                    ),\n                                  ),\n                                ],\n                              ),\n                            ),\n                            if (!isCompact)\n                              Container(\n                                padding: const EdgeInsets.symmetric(\n                                  horizontal: 10,\n                                  vertical: 6,\n                                ),\n                                decoration: BoxDecoration(\n                                  color: Colors.black.withValues(alpha: 0.55),\n                                  borderRadius: BorderRadius.circular(6),\n                                  border: Border.all(color: Colors.white24),\n                                ),\n                                child: const Text(\n                                  'WASD/ARROWS: Move & Aim | SPACE: Jump | J/X/CLICK: Shoot',\n                                  style: TextStyle(\n                                    color: Colors.white70,\n                                    fontFamily: 'JetBrainsMono',\n                                    fontSize: 11,\n                                  ),\n                                ),\n                              ),\n                          ],\n                        ),\n                      ],\n                    ),\n                  ),\n                ),\n\n                // Contra-style Touch Controls: Left Virtual Joystick + Right JUMP & SHOOT buttons\n                Positioned(\n                  left: isCompact ? 16 : 28,\n                  bottom: isCompact ? 16 : 24,\n                  child: Listener(\n                    behavior: HitTestBehavior.opaque,\n                    onPointerDown: (event) {\n                      if (_joystickPointerId == null) {\n                        setState(() {\n                          _joystickPointerId = event.pointer;\n                          _joystickCenter = Offset(joystickRadius, joystickRadius);\n                          _updateJoystickVector(\n                            event.localPosition,\n                            joystickRadius * 0.68,\n                          );\n                        });\n                      }\n                    },\n                    onPointerMove: (event) {\n                      if (event.pointer == _joystickPointerId) {\n                        setState(() {\n                          _updateJoystickVector(\n                            event.localPosition,\n                            joystickRadius * 0.68,\n                          );\n                        });\n                      }\n                    },\n                    onPointerUp: (event) {\n                      if (event.pointer == _joystickPointerId) {\n                        setState(() {\n                          _joystickPointerId = null;\n                          _joystickDelta = Offset.zero;\n                        });\n                      }\n                    },\n                    onPointerCancel: (event) {\n                      if (event.pointer == _joystickPointerId) {\n                        setState(() {\n                          _joystickPointerId = null;\n                          _joystickDelta = Offset.zero;\n                        });\n                      }\n                    },\n                    child: SizedBox(\n                      key: const Key('virtual_joystick'),\n                      width: joystickSize,\n                      height: joystickSize,\n                      child: CustomPaint(\n                        painter: _JoystickPainter(\n                          delta: _joystickDelta,\n                          isActive: _joystickPointerId != null,\n                        ),\n                      ),\n                    ),\n                  ),\n                ),\n\n                // Right-side JUMP and SHOOT arcade buttons\n                Positioned(\n                  right: isCompact ? 16 : 28,\n                  bottom: isCompact ? 18 : 26,\n                  child: Row(\n                    mainAxisSize: MainAxisSize.min,\n                    crossAxisAlignment: CrossAxisAlignment.end,\n                    children: [\n                      // JUMP Button\n                      Padding(\n                        padding: const EdgeInsets.only(bottom: 6, right: 14),\n                        child: Listener(\n                          behavior: HitTestBehavior.opaque,\n                          onPointerDown: (event) {\n                            _jumpButtonPointerId = event.pointer;\n                            _triggerJump();\n                          },\n                          onPointerUp: (event) {\n                            if (event.pointer == _jumpButtonPointerId) {\n                              setState(() => _jumpButtonPointerId = null);\n                            }\n                          },\n                          onPointerCancel: (event) {\n                            if (event.pointer == _jumpButtonPointerId) {\n                              setState(() => _jumpButtonPointerId = null);\n                            }\n                          },\n                          child: _ArcadeControlButton(\n                            key: const Key('jump_button'),\n                            label: 'JUMP',\n                            subLabel: 'SPACE',\n                            color: const Color(0xFF1D4ED8),\n                            isPressed: _jumpButtonPointerId != null,\n                            size: isCompact ? 68 : 74,\n                          ),\n                        ),\n                      ),\n                      // SHOOT Button (Hold for auto-fire)\n                      Padding(\n                        padding: const EdgeInsets.only(bottom: 22),\n                        child: Listener(\n                          behavior: HitTestBehavior.opaque,\n                          onPointerDown: (event) {\n                            setState(() => _shootButtonPointerId = event.pointer);\n                            _fireWeapon();\n                          },\n                          onPointerUp: (event) {\n                            if (event.pointer == _shootButtonPointerId) {\n                              setState(() => _shootButtonPointerId = null);\n                            }\n                          },\n                          onPointerCancel: (event) {\n                            if (event.pointer == _shootButtonPointerId) {\n                              setState(() => _shootButtonPointerId = null);\n                            }\n                          },\n                          child: _ArcadeControlButton(\n                            key: const Key('shoot_button'),\n                            label: 'SHOOT',\n                            subLabel: 'FIRE',\n                            color: kCrimsonRed,\n                            isPressed: _shootButtonPointerId != null,\n                            size: isCompact ? 76 : 82,\n                          ),\n                        ),\n                      ),\n                    ],\n                  ),\n                ),\n              ],\n            );\n          },\n        ),\n      ),\n    );\n  }\n}\n\nclass _ArcadeControlButton extends StatelessWidget {\n  final String label;\n  final String subLabel;\n  final Color color;\n  final bool isPressed;\n  final double size;\n\n  const _ArcadeControlButton({\n    super.key,\n    required this.label,\n    required this.subLabel,\n    required this.color,\n    required this.isPressed,\n    required this.size,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return AnimatedScale(\n      scale: isPressed ? 0.92 : 1.0,\n      duration: const Duration(milliseconds: 60),\n      child: Container(\n        width: size,\n        height: size,\n        decoration: BoxDecoration(\n          shape: BoxShape.circle,\n          color: isPressed\n              ? color.withValues(alpha: 0.85)\n              : color.withValues(alpha: 0.55),\n          border: Border.all(\n            color: Colors.white.withValues(alpha: isPressed ? 0.95 : 0.65),\n            width: 2.5,\n          ),\n          boxShadow: [\n            BoxShadow(\n              color: color.withValues(alpha: isPressed ? 0.65 : 0.3),\n              blurRadius: isPressed ? 14 : 8,\n              spreadRadius: isPressed ? 2 : 0,\n            ),\n          ],\n        ),\n        child: Center(\n          child: Column(\n            mainAxisSize: MainAxisSize.min,\n            children: [\n              Text(\n                label,\n                style: const TextStyle(\n                  color: Colors.white,\n                  fontFamily: 'JetBrainsMono',\n                  fontWeight: FontWeight.bold,\n                  fontSize: 13,\n                  letterSpacing: 0.8,\n                ),\n              ),\n              Text(\n                subLabel,\n                style: TextStyle(\n                  color: Colors.white.withValues(alpha: 0.7),\n                  fontFamily: 'JetBrainsMono',\n                  fontSize: 9,\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}\n\nclass _JoystickPainter extends CustomPainter {\n  final Offset delta;\n  final bool isActive;\n\n  _JoystickPainter({required this.delta, required this.isActive});\n\n  @override\n  void paint(Canvas canvas, Size size) {\n    final Offset center = size.center(Offset.zero);\n    final double radius = size.width / 2;\n\n    // Outer base circle\n    final Paint baseFill = Paint()\n      ..color = Colors.black.withValues(alpha: 0.45)\n      ..style = PaintingStyle.fill;\n    final Paint baseBorder = Paint()\n      ..color = Colors.white.withValues(alpha: isActive ? 0.75 : 0.38)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 2.2;\n\n    canvas.drawCircle(center, radius - 2, baseFill);\n    canvas.drawCircle(center, radius - 2, baseBorder);\n\n    // 8-direction tick marks\n    final Paint tickPaint = Paint()\n      ..color = Colors.white.withValues(alpha: 0.28)\n      ..strokeWidth = 1.5\n      ..strokeCap = StrokeCap.round;\n    for (int i = 0; i < 8; i++) {\n      final double a = i * (pi / 4);\n      final Offset p1 = center + Offset(cos(a), sin(a)) * (radius * 0.58);\n      final Offset p2 = center + Offset(cos(a), sin(a)) * (radius * 0.80);\n      canvas.drawLine(p1, p2, tickPaint);\n    }\n\n    // Thumbstick knob\n    final Offset knobPos = center + delta * (radius * 0.52);\n    final Paint stemPaint = Paint()\n      ..color = Colors.white38\n      ..strokeWidth = 5\n      ..strokeCap = StrokeCap.round;\n    canvas.drawLine(center, knobPos, stemPaint);\n\n    final Paint knobFill = Paint()\n      ..color = isActive\n          ? kCrimsonRed.withValues(alpha: 0.9)\n          : const Color(0xFF475569).withValues(alpha: 0.85);\n    final Paint knobBorder = Paint()\n      ..color = Colors.white.withValues(alpha: 0.85)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 2.0;\n\n    canvas.drawCircle(knobPos, radius * 0.34, knobFill);\n    canvas.drawCircle(knobPos, radius * 0.34, knobBorder);\n  }\n\n  @override\n  bool shouldRepaint(covariant _JoystickPainter oldDelegate) =>\n      oldDelegate.delta != delta || oldDelegate.isActive != isActive;\n}\n\nclass _RudolphContraPainter extends CustomPainter {\n  final double worldTime;\n  final double playerX;\n  final double playerY;\n  final bool facingRight;\n  final double aimAngle;\n  final double walkCycle;\n  final bool isGrounded;\n  final double muzzleFlashTimer;\n  final double recoilOffset;\n  final int kills;\n  final List<_Platform> platforms;\n  final List<_Bullet> bullets;\n  final List<_ReindeerTarget> reindeer;\n  final List<_BloodParticle> bloodParticles;\n  final List<_SnowStain> snowStains;\n  final List<_ShellCasing> shells;\n  final List<_FloatingText> floatingTexts;\n  final List<_HorizonCross> horizonCrosses;\n  final List<_Snowflake> snowflakes;\n  final List<_Star> stars;\n\n  _RudolphContraPainter({\n    required this.worldTime,\n    required this.playerX,\n    required this.playerY,\n    required this.facingRight,\n    required this.aimAngle,\n    required this.walkCycle,\n    required this.isGrounded,\n    required this.muzzleFlashTimer,\n    required this.recoilOffset,\n    required this.kills,\n    required this.platforms,\n    required this.bullets,\n    required this.reindeer,\n    required this.bloodParticles,\n    required this.snowStains,\n    required this.shells,\n    required this.floatingTexts,\n    required this.horizonCrosses,\n    required this.snowflakes,\n    required this.stars,\n  });\n\n  @override\n  void paint(Canvas canvas, Size size) {\n    _drawNightSkyAndStars(canvas, size);\n    _drawGrinningMoon(canvas, size);\n    _drawDistantMountainsAndCrosses(canvas, size);\n    _drawSnowcappedTreesAndGingerbread(canvas, size);\n    _drawMainSnowGround(canvas, size);\n    _drawPlatforms(canvas, size);\n    _drawSnowBloodStains(canvas, size);\n    _drawShellCasings(canvas, size);\n\n    // Draw unarmed target reindeer\n    for (final r in reindeer) {\n      _drawCartoonReindeerTarget(canvas, size, r);\n    }\n\n    // Draw playable Rudolph commando\n    _drawRudolphCommando(canvas, size);\n\n    // Draw bullets & blood particles\n    _drawBullets(canvas, size);\n    _drawBloodParticles(canvas, size);\n    _drawFloatingTexts(canvas, size);\n    _drawSnowfall(canvas, size);\n  }\n\n  void _drawNightSkyAndStars(Canvas canvas, Size size) {\n    final Rect skyRect = Offset.zero & size;\n    final Paint skyPaint = Paint()\n      ..shader = const LinearGradient(\n        begin: Alignment.topCenter,\n        end: Alignment.bottomCenter,\n        colors: [kNightTop, kNightBottom, Color(0xFF1B2A4A)],\n        stops: [0.0, 0.55, 0.85],\n      ).createShader(skyRect);\n    canvas.drawRect(skyRect, skyPaint);\n\n    final Paint starPaint = Paint()..style = PaintingStyle.fill;\n    for (final s in stars) {\n      final double alpha = 0.45 + 0.55 * sin(worldTime * 2.2 + s.twinklePhase).abs();\n      starPaint.color = Colors.white.withValues(alpha: alpha);\n      canvas.drawCircle(\n        Offset(s.x * size.width, s.y * size.height),\n        s.size,\n        starPaint,\n      );\n    }\n  }\n\n  void _drawGrinningMoon(Canvas canvas, Size size) {\n    // \"The moon grins down onto the snowcapped trees.\"\n    final Offset moonCenter = Offset(size.width * 0.80, size.height * 0.16);\n    final double moonRadius = min(size.width, size.height) * 0.085;\n\n    // Outer lunar glow\n    for (int i = 3; i >= 1; i--) {\n      final Paint glowPaint = Paint()\n        ..color = const Color(0xFFFFF3B0).withValues(alpha: 0.06 * i);\n      canvas.drawCircle(moonCenter, moonRadius * (1.0 + i * 0.35), glowPaint);\n    }\n\n    // Moon body with cartoon outline\n    final Paint moonFill = Paint()\n      ..shader = RadialGradient(\n        center: const Alignment(-0.25, -0.25),\n        radius: 0.9,\n        colors: const [Color(0xFFFFFAE5), Color(0xFFFDE68A), Color(0xFFF59E0B)],\n      ).createShader(Rect.fromCircle(center: moonCenter, radius: moonRadius));\n    final Paint outlinePaint = Paint()\n      ..color = const Color(0xFF1E293B)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 2.5;\n\n    canvas.drawCircle(moonCenter, moonRadius, moonFill);\n    canvas.drawCircle(moonCenter, moonRadius, outlinePaint);\n\n    // Subtle moon craters\n    final Paint craterPaint = Paint()\n      ..color = const Color(0xFFD97706).withValues(alpha: 0.22);\n    canvas.drawCircle(\n      moonCenter + Offset(-moonRadius * 0.42, -moonRadius * 0.35),\n      moonRadius * 0.16,\n      craterPaint,\n    );\n    canvas.drawCircle(\n      moonCenter + Offset(moonRadius * 0.48, -moonRadius * 0.12),\n      moonRadius * 0.12,\n      craterPaint,\n    );\n\n    // Mischievous cartoon eyes looking down at the snowfield\n    final Paint eyeWhite = Paint()..color = Colors.white;\n    final Paint pupilPaint = Paint()..color = const Color(0xFF0F172A);\n    final Offset leftEye = moonCenter + Offset(-moonRadius * 0.28, -moonRadius * 0.12);\n    final Offset rightEye = moonCenter + Offset(moonRadius * 0.22, -moonRadius * 0.12);\n    canvas.drawOval(\n      Rect.fromCenter(\n        center: leftEye,\n        width: moonRadius * 0.28,\n        height: moonRadius * 0.22,\n      ),\n      eyeWhite,\n    );\n    canvas.drawOval(\n      Rect.fromCenter(\n        center: rightEye,\n        width: moonRadius * 0.28,\n        height: moonRadius * 0.22,\n      ),\n      eyeWhite,\n    );\n    canvas.drawCircle(\n      leftEye + Offset(-moonRadius * 0.03, moonRadius * 0.04),\n      moonRadius * 0.07,\n      pupilPaint,\n    );\n    canvas.drawCircle(\n      rightEye + Offset(-moonRadius * 0.03, moonRadius * 0.04),\n      moonRadius * 0.07,\n      pupilPaint,\n    );\n\n    // Angry/sly brow line\n    final Paint browPaint = Paint()\n      ..color = const Color(0xFF1E293B)\n      ..strokeWidth = 2.4\n      ..strokeCap = StrokeCap.round;\n    canvas.drawLine(\n      leftEye + Offset(-moonRadius * 0.15, -moonRadius * 0.13),\n      leftEye + Offset(moonRadius * 0.12, -moonRadius * 0.06),\n      browPaint,\n    );\n    canvas.drawLine(\n      rightEye + Offset(-moonRadius * 0.12, -moonRadius * 0.06),\n      rightEye + Offset(moonRadius * 0.15, -moonRadius * 0.13),\n      browPaint,\n    );\n\n    // Wide cartoon grin with teeth\n    final Path grinPath = Path()\n      ..moveTo(moonCenter.dx - moonRadius * 0.52, moonCenter.dy + moonRadius * 0.12)\n      ..quadraticBezierTo(\n        moonCenter.dx,\n        moonCenter.dy + moonRadius * 0.65,\n        moonCenter.dx + moonRadius * 0.52,\n        moonCenter.dy + moonRadius * 0.10,\n      )\n      ..quadraticBezierTo(\n        moonCenter.dx,\n        moonCenter.dy + moonRadius * 0.35,\n        moonCenter.dx - moonRadius * 0.52,\n        moonCenter.dy + moonRadius * 0.12,\n      )\n      ..close();\n\n    canvas.drawPath(grinPath, Paint()..color = Colors.white);\n    canvas.drawPath(grinPath, outlinePaint);\n\n    // Grin teeth dividers\n    final Paint toothLine = Paint()\n      ..color = const Color(0xFF1E293B)\n      ..strokeWidth = 1.5;\n    for (int t = -2; t <= 2; t++) {\n      final double tx = moonCenter.dx + t * moonRadius * 0.15;\n      canvas.drawLine(\n        Offset(tx, moonCenter.dy + moonRadius * 0.22),\n        Offset(tx, moonCenter.dy + moonRadius * 0.37),\n        toothLine,\n      );\n    }\n  }\n\n  void _drawDistantMountainsAndCrosses(Canvas canvas, Size size) {\n    final double horizonY = size.height * 0.68;\n\n    // Distant snow-covered mountain range\n    final Path mountainPath = Path()\n      ..moveTo(0, size.height)\n      ..lineTo(0, horizonY)\n      ..lineTo(size.width * 0.14, size.height * 0.50)\n      ..lineTo(size.width * 0.29, horizonY - 10)\n      ..lineTo(size.width * 0.48, size.height * 0.45)\n      ..lineTo(size.width * 0.66, horizonY - 5)\n      ..lineTo(size.width * 0.84, size.height * 0.52)\n      ..lineTo(size.width, horizonY - 12)\n      ..lineTo(size.width, size.height)\n      ..close();\n\n    canvas.drawPath(\n      mountainPath,\n      Paint()..color = const Color(0xFF1E2D4D),\n    );\n\n    // Rolling mid-ground snow hills\n    final Path hillPath = Path()\n      ..moveTo(0, size.height)\n      ..lineTo(0, horizonY + 8)\n      ..quadraticBezierTo(\n        size.width * 0.25,\n        horizonY - 22,\n        size.width * 0.52,\n        horizonY + 6,\n      )\n      ..quadraticBezierTo(\n        size.width * 0.78,\n        horizonY - 20,\n        size.width,\n        horizonY + 4,\n      )\n      ..lineTo(size.width, size.height)\n      ..close();\n\n    canvas.drawPath(\n      hillPath,\n      Paint()..color = const Color(0xFF334E68),\n    );\n\n    // \"The next day, the crosses lined the horizon.\"\n    final Paint crossPaint = Paint()\n      ..color = const Color(0xFF0F172A)\n      ..strokeWidth = 2.6\n      ..strokeCap = StrokeCap.round;\n    for (final c in horizonCrosses) {\n      final double cx = c.x * size.width;\n      final double cy = horizonY - 6;\n      canvas.save();\n      canvas.translate(cx, cy);\n      canvas.rotate(c.tilt);\n      canvas.drawLine(const Offset(0, 4), const Offset(0, -18), crossPaint);\n      canvas.drawLine(const Offset(-6, -11), const Offset(6, -11), crossPaint);\n      canvas.restore();\n    }\n  }\n\n  void _drawSnowcappedTreesAndGingerbread(Canvas canvas, Size size) {\n    final double groundPx = size.height * 0.80;\n\n    // Distant gingerbread house silhouette with billowing chimney (\"Gingerbread house with a chimney that billows\")\n    final double houseX = size.width * 0.11;\n    final double houseY = groundPx - 36;\n    final Paint housePaint = Paint()..color = const Color(0xFF5C3A21);\n    final Paint outline = Paint()\n      ..color = const Color(0xFF0F172A)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 2.0;\n\n    // Chimney smoke puffs\n    for (int i = 0; i < 4; i++) {\n      final double puffProgress = ((worldTime * 0.4 + i * 0.25) % 1.0);\n      final Offset puffCenter = Offset(\n        houseX + 18 + sin(worldTime * 2 + i) * 6,\n        houseY - 18 - puffProgress * 38,\n      );\n      canvas.drawCircle(\n        puffCenter,\n        5 + puffProgress * 9,\n        Paint()..color = Colors.white.withValues(alpha: (1 - puffProgress) * 0.28),\n      );\n    }\n\n    canvas.drawRect(\n      Rect.fromLTWH(houseX + 13, houseY - 16, 9, 18),\n      housePaint,\n    );\n    canvas.drawRect(\n      Rect.fromLTWH(houseX - 18, houseY, 38, 36),\n      housePaint,\n    );\n    canvas.drawRect(\n      Rect.fromLTWH(houseX - 18, houseY, 38, 36),\n      outline,\n    );\n    // Warm glowing window\n    canvas.drawRect(\n      Rect.fromLTWH(houseX - 6, houseY + 10, 12, 12),\n      Paint()..color = const Color(0xFFFBBF24),\n    );\n    // Snow-frosted roof\n    final Path roofSnow = Path()\n      ..moveTo(houseX - 24, houseY + 3)\n      ..lineTo(houseX + 1, houseY - 18)\n      ..lineTo(houseX + 26, houseY + 3)\n      ..close();\n    canvas.drawPath(roofSnow, Paint()..color = kSnowWhite);\n    canvas.drawPath(roofSnow, outline);\n\n    // Snowcapped pine trees across the background\n    final List<double> treePositions = [0.04, 0.21, 0.37, 0.54, 0.72, 0.91];\n    for (int i = 0; i < treePositions.length; i++) {\n      final double tx = treePositions[i] * size.width;\n      final double scale = (i.isEven ? 1.0 : 0.82);\n      _drawSingleSnowTree(canvas, Offset(tx, groundPx), 68 * scale);\n    }\n  }\n\n  void _drawSingleSnowTree(Canvas canvas, Offset base, double height) {\n    final Paint trunkPaint = Paint()..color = const Color(0xFF4A2C11);\n    final Paint pinePaint = Paint()..color = const Color(0xFF14532D);\n    final Paint snowCapPaint = Paint()..color = kSnowWhite;\n    final Paint outline = Paint()\n      ..color = const Color(0xFF0B132B)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 1.8;\n\n    canvas.drawRect(\n      Rect.fromCenter(\n        center: base - Offset(0, height * 0.1),\n        width: height * 0.16,\n        height: height * 0.22,\n      ),\n      trunkPaint,\n    );\n\n    for (int tier = 0; tier < 3; tier++) {\n      final double tierBottom = base.dy - height * (0.18 + tier * 0.24);\n      final double tierTop = tierBottom - height * 0.36;\n      final double halfWidth = height * (0.38 - tier * 0.07);\n\n      final Path foliage = Path()\n        ..moveTo(base.dx, tierTop)\n        ..lineTo(base.dx - halfWidth, tierBottom)\n        ..lineTo(base.dx + halfWidth, tierBottom)\n        ..close();\n      canvas.drawPath(foliage, pinePaint);\n      canvas.drawPath(foliage, outline);\n\n      // Thick cartoon snow cap on top of each pine tier\n      final Path snowCap = Path()\n        ..moveTo(base.dx, tierTop)\n        ..lineTo(base.dx - halfWidth * 0.58, tierTop + (tierBottom - tierTop) * 0.52)\n        ..quadraticBezierTo(\n          base.dx,\n          tierTop + (tierBottom - tierTop) * 0.66,\n          base.dx + halfWidth * 0.58,\n          tierTop + (tierBottom - tierTop) * 0.52,\n        )\n        ..close();\n      canvas.drawPath(snowCap, snowCapPaint);\n    }\n  }\n\n  void _drawMainSnowGround(Canvas canvas, Size size) {\n    final double groundY = size.height * 0.80;\n\n    // Deep snowbank fill\n    final Rect snowRect = Rect.fromLTWH(0, groundY, size.width, size.height - groundY);\n    final Paint snowPaint = Paint()\n      ..shader = const LinearGradient(\n        begin: Alignment.topCenter,\n        end: Alignment.bottomCenter,\n        colors: [kSnowWhite, Color(0xFFD9E2EC), Color(0xFF9FB3C8)],\n      ).createShader(snowRect);\n    canvas.drawRect(snowRect, snowPaint);\n\n    // Cartoon wavy snowdrift ridge line\n    final Path driftPath = Path()..moveTo(0, groundY);\n    for (double x = 0; x <= size.width; x += size.width / 8) {\n      driftPath.quadraticBezierTo(\n        x + size.width / 16,\n        groundY - 5,\n        x + size.width / 8,\n        groundY,\n      );\n    }\n    canvas.drawPath(\n      driftPath,\n      Paint()\n        ..color = const Color(0xFF1E293B)\n        ..style = PaintingStyle.stroke\n        ..strokeWidth = 2.5,\n    );\n  }\n\n  void _drawPlatforms(Canvas canvas, Size size) {\n    final Paint rockPaint = Paint()..color = const Color(0xFF334155);\n    final Paint snowTopPaint = Paint()..color = kSnowWhite;\n    final Paint outline = Paint()\n      ..color = const Color(0xFF0F172A)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 2.2;\n\n    for (final p in platforms) {\n      final double left = p.xMin * size.width;\n      final double right = p.xMax * size.width;\n      final double top = p.y * size.height;\n      final double width = right - left;\n\n      // Icy rock base\n      final RRect baseRect = RRect.fromRectAndRadius(\n        Rect.fromLTWH(left, top, width, 18),\n        const Radius.circular(8),\n      );\n      canvas.drawRRect(baseRect, rockPaint);\n      canvas.drawRRect(baseRect, outline);\n\n      // Thick snow blanket on top of the ledge\n      final RRect snowCap = RRect.fromRectAndRadius(\n        Rect.fromLTWH(left - 3, top - 4, width + 6, 11),\n        const Radius.circular(6),\n      );\n      canvas.drawRRect(snowCap, snowTopPaint);\n      canvas.drawRRect(snowCap, outline);\n    }\n  }\n\n  void _drawSnowBloodStains(Canvas canvas, Size size) {\n    for (final stain in snowStains) {\n      final Offset center = Offset(\n        stain.x * size.width,\n        stain.y * size.height + 2,\n      );\n      final Rect oval = Rect.fromCenter(\n        center: center,\n        width: stain.radiusX * size.width,\n        height: stain.radiusY * size.height + 4,\n      );\n      canvas.drawOval(\n        oval,\n        Paint()..color = kCrimsonRed.withValues(alpha: 0.82),\n      );\n      canvas.drawOval(\n        oval.deflate(2),\n        Paint()..color = kDarkBlood.withValues(alpha: 0.65),\n      );\n    }\n  }\n\n  void _drawShellCasings(Canvas canvas, Size size) {\n    final Paint brassPaint = Paint()..color = const Color(0xFFF59E0B);\n    for (final s in shells) {\n      canvas.save();\n      canvas.translate(s.x * size.width, s.y * size.height);\n      canvas.rotate(s.rotation);\n      canvas.drawRect(\n        const Rect.fromLTWH(-3, -1.5, 6, 3),\n        brassPaint,\n      );\n      canvas.restore();\n    }\n  }\n\n  void _drawCartoonReindeerTarget(\n    Canvas canvas,\n    Size size,\n    _ReindeerTarget r,\n  ) {\n    final double cx = r.x * size.width;\n    final double cy = r.y * size.height;\n    final bool movingRight = r.vx >= 0;\n    final bool panicked = r.panicTimer > 0;\n\n    // Fur palette variations so each reindeer looks distinct and detailed\n    final List<Color> coatColors = [\n      const Color(0xFF8D5524),\n      const Color(0xFFA0522D),\n      const Color(0xFF6F4E37),\n    ];\n    final Color mainCoat = r.hitFlash > 0\n        ? kCrimsonRed\n        : coatColors[r.furVariant % coatColors.length];\n    const Color bellyCream = Color(0xFFF3E5AB);\n    const Color darkHoof = Color(0xFF1F1610);\n    const Color antlerTan = Color(0xFFD2B48C);\n\n    final Paint coatPaint = Paint()..color = mainCoat;\n    final Paint bellyPaint = Paint()..color = bellyCream;\n    final Paint outline = Paint()\n      ..color = const Color(0xFF1A110B)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 2.2\n      ..strokeJoin = StrokeJoin.round;\n\n    canvas.save();\n    canvas.translate(cx, cy);\n\n    // Shadow on snow\n    if (!r.isFlying) {\n      canvas.drawOval(\n        Rect.fromCenter(center: const Offset(0, 0), width: 48, height: 10),\n        Paint()..color = Colors.black.withValues(alpha: 0.28),\n      );\n    }\n\n    canvas.save();\n    if (!movingRight) {\n      canvas.scale(-1, 1);\n    }\n\n    // Animated 4-legged deer gallop/walk cycle\n    final double swing = sin(r.legPhase) * (panicked ? 11.0 : 7.0);\n    final double swingOpp = cos(r.legPhase) * (panicked ? 11.0 : 7.0);\n\n    void drawDeerLeg(Offset hip, double angleOffset, bool isBackLayer) {\n      final Paint legPaint = Paint()\n        ..color = isBackLayer\n            ? Color.lerp(mainCoat, Colors.black, 0.25)!\n            : mainCoat\n        ..strokeWidth = 5.5\n        ..strokeCap = StrokeCap.round;\n      final Offset knee = hip + Offset(angleOffset * 0.45, 11);\n      final Offset hoof = knee + Offset(angleOffset * 0.65, 11);\n      canvas.drawLine(hip, knee, legPaint);\n      canvas.drawLine(knee, hoof, legPaint);\n\n      // Cloven hoof\n      final Path hoofPath = Path()\n        ..moveTo(hoof.dx - 3, hoof.dy - 2)\n        ..lineTo(hoof.dx + 4, hoof.dy - 2)\n        ..lineTo(hoof.dx + 5, hoof.dy + 3)\n        ..lineTo(hoof.dx - 3, hoof.dy + 3)\n        ..close();\n      canvas.drawPath(hoofPath, Paint()..color = darkHoof);\n    }\n\n    // Back legs\n    drawDeerLeg(const Offset(-14, -22), swingOpp, true);\n    drawDeerLeg(const Offset(12, -22), -swing, true);\n\n    // Fluffy white deer tail\n    final Path tailPath = Path()\n      ..moveTo(-20, -32)\n      ..quadraticBezierTo(-32, -40, -28, -26)\n      ..quadraticBezierTo(-24, -22, -18, -26)\n      ..close();\n    canvas.drawPath(tailPath, bellyPaint);\n    canvas.drawPath(tailPath, outline);\n\n    // Reindeer torso (sleek cartoon deer body with cream underbelly and spots)\n    final RRect bodyRRect = RRect.fromRectAndRadius(\n      Rect.fromCenter(center: const Offset(-2, -29), width: 42, height: 20),\n      const Radius.circular(10),\n    );\n    canvas.drawRRect(bodyRRect, coatPaint);\n\n    // Cream underbelly trim\n    canvas.drawArc(\n      Rect.fromCenter(center: const Offset(-2, -23), width: 34, height: 10),\n      0,\n      pi,\n      false,\n      bellyPaint,\n    );\n\n    // White fawn spots on back\n    final Paint spotPaint = Paint()\n      ..color = Colors.white.withValues(alpha: 0.55);\n    canvas.drawCircle(const Offset(-12, -33), 2.5, spotPaint);\n    canvas.drawCircle(const Offset(-5, -35), 2.0, spotPaint);\n    canvas.drawCircle(const Offset(-9, -29), 1.8, spotPaint);\n    canvas.drawRRect(bodyRRect, outline);\n\n    // Front legs\n    drawDeerLeg(const Offset(-12, -22), swing, false);\n    drawDeerLeg(const Offset(14, -22), -swingOpp, false);\n\n    // Long reindeer neck & festive red/green jingle bell collar\n    final Path neckPath = Path()\n      ..moveTo(8, -33)\n      ..lineTo(18, -50)\n      ..lineTo(26, -46)\n      ..lineTo(18, -24)\n      ..close();\n    canvas.drawPath(neckPath, coatPaint);\n    canvas.drawPath(neckPath, outline);\n\n    // Festive collar + gold jingle bells\n    final Paint collarPaint = Paint()\n      ..color = const Color(0xFFB91C1C)\n      ..strokeWidth = 4.5\n      ..strokeCap = StrokeCap.round;\n    canvas.drawLine(const Offset(10, -36), const Offset(21, -30), collarPaint);\n    canvas.drawCircle(\n      const Offset(16, -32),\n      3.2,\n      Paint()..color = const Color(0xFFFACC15),\n    );\n\n    // Multi-pronged branching antlers (unmistakably a reindeer!)\n    final Paint antlerPaint = Paint()\n      ..color = antlerTan\n      ..strokeWidth = 3.2\n      ..strokeCap = StrokeCap.round\n      ..style = PaintingStyle.stroke;\n    final Paint antlerOutline = Paint()\n      ..color = const Color(0xFF1A110B)\n      ..strokeWidth = 5.0\n      ..strokeCap = StrokeCap.round\n      ..style = PaintingStyle.stroke;\n\n    final Path antlers = Path()\n      // Back antler beam + tines\n      ..moveTo(19, -54)\n      ..lineTo(11, -72)\n      ..moveTo(15, -63)\n      ..lineTo(7, -66)\n      ..moveTo(13, -68)\n      ..lineTo(18, -75)\n      // Front antler beam + tines\n      ..moveTo(22, -54)\n      ..lineTo(20, -75)\n      ..moveTo(21, -64)\n      ..lineTo(28, -68)\n      ..moveTo(20, -70)\n      ..lineTo(14, -77);\n    canvas.drawPath(antlers, antlerOutline);\n    canvas.drawPath(antlers, antlerPaint);\n\n    // Reindeer ear\n    final Path earPath = Path()\n      ..moveTo(16, -50)\n      ..quadraticBezierTo(6, -56, 9, -46)\n      ..close();\n    canvas.drawPath(earPath, coatPaint);\n    canvas.drawPath(earPath, outline);\n\n    // Reindeer head & elongated snout\n    final Path headPath = Path()\n      ..moveTo(14, -52)\n      ..quadraticBezierTo(24, -58, 29, -50)\n      ..lineTo(39, -47)\n      ..quadraticBezierTo(41, -41, 34, -39)\n      ..lineTo(18, -41)\n      ..close();\n    canvas.drawPath(headPath, coatPaint);\n    canvas.drawPath(headPath, outline);\n\n    // Dark reindeer nose (non-glowing)\n    canvas.drawCircle(\n      const Offset(38, -45),\n      3.2,\n      Paint()..color = darkHoof,\n    );\n\n    // Expressive cartoon eye (wide-eyed panic when Rudolph shoots!)\n    final Offset eyeCenter = const Offset(25, -48);\n    canvas.drawCircle(\n      eyeCenter,\n      panicked ? 4.4 : 3.4,\n      Paint()..color = Colors.white,\n    );\n    canvas.drawCircle(\n      eyeCenter,\n      panicked ? 4.4 : 3.4,\n      Paint()\n        ..color = Colors.black\n        ..style = PaintingStyle.stroke\n        ..strokeWidth = 1.3,\n    );\n    canvas.drawCircle(\n      eyeCenter + Offset(panicked ? -0.5 : 0.8, 0),\n      panicked ? 1.6 : 1.8,\n      Paint()..color = Colors.black,\n    );\n\n    // Open shocked mouth & sweat drop when panicked\n    if (panicked) {\n      canvas.drawOval(\n        Rect.fromCenter(center: const Offset(31, -41), width: 6, height: 4),\n        Paint()..color = const Color(0xFF7F1D1D),\n      );\n    }\n\n    canvas.restore(); // restore flip\n\n    // Name tag + HP bar above reindeer\n    final TextPainter nameTp = TextPainter(\n      text: TextSpan(\n        text: r.name,\n        style: TextStyle(\n          color: panicked ? const Color(0xFFFCA5A5) : Colors.white,\n          fontFamily: 'JetBrainsMono',\n          fontSize: 10,\n          fontWeight: FontWeight.bold,\n          shadows: const [Shadow(color: Colors.black, blurRadius: 4)],\n        ),\n      ),\n      textDirection: TextDirection.ltr,\n    )..layout();\n    nameTp.paint(canvas, Offset(-nameTp.width / 2, -88));\n\n    // Mini health bar if damaged\n    if (r.hp < r.maxHp) {\n      const double barW = 30;\n      canvas.drawRect(\n        const Rect.fromLTWH(-barW / 2, -74, barW, 4),\n        Paint()..color = Colors.black54,\n      );\n      canvas.drawRect(\n        Rect.fromLTWH(-barW / 2, -74, barW * (r.hp / r.maxHp), 4),\n        Paint()..color = kCrimsonRed,\n      );\n    }\n\n    canvas.restore();\n  }\n\n  void _drawRudolphCommando(Canvas canvas, Size size) {\n    final double cx = playerX * size.width;\n    final double cy = playerY * size.height;\n\n    const Color rudolphCoat = Color(0xFF9A5B25);\n    const Color bellyCream = Color(0xFFF5E6C4);\n    const Color darkHoof = Color(0xFF1A110B);\n    const Color antlerColor = Color(0xFFE6CCB2);\n\n    final Paint coatPaint = Paint()..color = rudolphCoat;\n    final Paint bellyPaint = Paint()..color = bellyCream;\n    final Paint outline = Paint()\n      ..color = const Color(0xFF140C06)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 2.4\n      ..strokeJoin = StrokeJoin.round;\n\n    canvas.save();\n    canvas.translate(cx, cy);\n\n    // Ground shadow\n    if (isGrounded) {\n      canvas.drawOval(\n        Rect.fromCenter(center: const Offset(0, 0), width: 54, height: 12),\n        Paint()..color = Colors.black.withValues(alpha: 0.35),\n      );\n    }\n\n    canvas.save();\n    if (!facingRight) {\n      canvas.scale(-1, 1);\n    }\n\n    final double legSwing = isGrounded ? sin(walkCycle) * 10.0 : 8.0;\n\n    // Hind reindeer legs in heroic action stance\n    void drawRudolphLeg(Offset hip, double swingOffset, bool isBack) {\n      final Paint legP = Paint()\n        ..color = isBack\n            ? Color.lerp(rudolphCoat, Colors.black, 0.22)!\n            : rudolphCoat\n        ..strokeWidth = 6.5\n        ..strokeCap = StrokeCap.round;\n      final Offset knee = hip + Offset(swingOffset * 0.5, 12);\n      final Offset hoof = knee + Offset(swingOffset * 0.7, 12);\n      canvas.drawLine(hip, knee, legP);\n      canvas.drawLine(knee, hoof, legP);\n      canvas.drawRect(\n        Rect.fromCenter(center: hoof, width: 8, height: 5),\n        Paint()..color = darkHoof,\n      );\n    }\n\n    drawRudolphLeg(const Offset(-12, -24), -legSwing, true);\n    drawRudolphLeg(const Offset(10, -24), legSwing, true);\n\n    // Fluffy white tail\n    canvas.drawOval(\n      Rect.fromCenter(center: const Offset(-23, -34), width: 12, height: 8),\n      bellyPaint,\n    );\n    canvas.drawOval(\n      Rect.fromCenter(center: const Offset(-23, -34), width: 12, height: 8),\n      outline,\n    );\n\n    // Muscular reindeer lower body + upright commando chest\n    final RRect lowerBody = RRect.fromRectAndRadius(\n      Rect.fromCenter(center: const Offset(-3, -30), width: 40, height: 20),\n      const Radius.circular(10),\n    );\n    canvas.drawRRect(lowerBody, coatPaint);\n    canvas.drawRRect(lowerBody, outline);\n\n    drawRudolphLeg(const Offset(-9, -24), legSwing, false);\n\n    // Upright chest & neck\n    final Path chestPath = Path()\n      ..moveTo(-6, -34)\n      ..lineTo(6, -58)\n      ..lineTo(20, -54)\n      ..lineTo(15, -26)\n      ..close();\n    canvas.drawPath(chestPath, coatPaint);\n    canvas.drawPath(\n      Path()\n        ..moveTo(8, -54)\n        ..lineTo(19, -52)\n        ..lineTo(15, -30)\n        ..lineTo(6, -32)\n        ..close(),\n      bellyPaint,\n    );\n    canvas.drawPath(chestPath, outline);\n\n    // Tactical ammo bandolier across Rudolph's chest\n    final Paint strapPaint = Paint()\n      ..color = const Color(0xFF1F2937)\n      ..strokeWidth = 5.0;\n    canvas.drawLine(const Offset(-3, -32), const Offset(15, -52), strapPaint);\n    for (int b = 0; b < 4; b++) {\n      final double t = b / 3.0;\n      final Offset shellPos = Offset(-1 + t * 14, -34 - t * 16);\n      canvas.drawCircle(\n        shellPos,\n        2.2,\n        Paint()..color = const Color(0xFFFBBF24),\n      );\n    }\n\n    // Large branching reindeer antlers (\"Antlers covered in stains of their enemies\")\n    final Path antlerPath = Path()\n      ..moveTo(7, -64)\n      ..lineTo(-5, -86)\n      ..moveTo(1, -74)\n      ..lineTo(-9, -77)\n      ..moveTo(-2, -80)\n      ..lineTo(5, -88)\n      ..moveTo(12, -64)\n      ..lineTo(11, -89)\n      ..moveTo(11, -75)\n      ..lineTo(20, -80)\n      ..moveTo(11, -82)\n      ..lineTo(4, -90);\n\n    canvas.drawPath(\n      antlerPath,\n      Paint()\n        ..color = const Color(0xFF140C06)\n        ..strokeWidth = 5.8\n        ..strokeCap = StrokeCap.round\n        ..style = PaintingStyle.stroke,\n    );\n    canvas.drawPath(\n      antlerPath,\n      Paint()\n        ..color = antlerColor\n        ..strokeWidth = 3.6\n        ..strokeCap = StrokeCap.round\n        ..style = PaintingStyle.stroke,\n    );\n\n    // Crimson blood stains on Rudolph's antlers when kills > 0\n    if (kills > 0) {\n      final Paint bloodAntler = Paint()\n        ..color = kCrimsonRed\n        ..strokeWidth = 3.8\n        ..strokeCap = StrokeCap.round\n        ..style = PaintingStyle.stroke;\n      final Path stainedTips = Path()\n        ..moveTo(-1, -79)\n        ..lineTo(-5, -86)\n        ..moveTo(11, -81)\n        ..lineTo(11, -89)\n        ..moveTo(15, -77)\n        ..lineTo(20, -80);\n      canvas.drawPath(stainedTips, bloodAntler);\n    }\n\n    // Rudolph's head, ear, and Contra red commando headband with trailing tails\n    final Path headbandTails = Path()\n      ..moveTo(2, -60)\n      ..quadraticBezierTo(-14, -64 + sin(worldTime * 12) * 4, -24, -56)\n      ..moveTo(2, -57)\n      ..quadraticBezierTo(-12, -57 + cos(worldTime * 12) * 4, -21, -50);\n    canvas.drawPath(\n      headbandTails,\n      Paint()\n        ..color = kCrimsonRed\n        ..strokeWidth = 3.5\n        ..strokeCap = StrokeCap.round\n        ..style = PaintingStyle.stroke,\n    );\n\n    final Path headPath = Path()\n      ..moveTo(3, -62)\n      ..quadraticBezierTo(14, -68, 21, -60)\n      ..lineTo(34, -56)\n      ..quadraticBezierTo(36, -49, 27, -47)\n      ..lineTo(8, -49)\n      ..close();\n    canvas.drawPath(headPath, coatPaint);\n    canvas.drawPath(headPath, outline);\n\n    // Red Contra headband across forehead\n    canvas.drawLine(\n      const Offset(4, -60),\n      const Offset(21, -59),\n      Paint()\n        ..color = kCrimsonRed\n        ..strokeWidth = 4.5\n        ..strokeCap = StrokeCap.round,\n    );\n\n    // Fierce cartoon commando eye with angry brow\n    canvas.drawOval(\n      Rect.fromCenter(center: const Offset(17, -56), width: 7, height: 5.5),\n      Paint()..color = Colors.white,\n    );\n    canvas.drawCircle(\n      const Offset(18.5, -56),\n      2.0,\n      Paint()..color = Colors.black,\n    );\n    canvas.drawLine(\n      const Offset(13, -60),\n      const Offset(21, -57),\n      Paint()\n        ..color = Colors.black\n        ..strokeWidth = 2.2,\n    );\n\n    // Glowing Red Nose (\"Please don't make light of a nose that's glowing\")\n    const Offset nosePos = Offset(34, -54);\n    for (int g = 3; g >= 1; g--) {\n      canvas.drawCircle(\n        nosePos,\n        4.5 + g * 4.5,\n        Paint()..color = kNoseGlow.withValues(alpha: 0.14 * g),\n      );\n    }\n    canvas.drawCircle(nosePos, 4.8, Paint()..color = const Color(0xFFFF002B));\n    canvas.drawCircle(\n      nosePos + const Offset(-1.2, -1.2),\n      1.6,\n      Paint()..color = Colors.white,\n    );\n\n    canvas.restore(); // restore horizontal flip so gun rotates accurately in world space\n\n    // Draw Contra Heavy Assault Rifle / Twelve-Gauge aimed along aimAngle\n    canvas.save();\n    final double recoilPx = recoilOffset * size.width;\n    canvas.translate(\n      -cos(aimAngle) * recoilPx,\n      -42 - sin(aimAngle) * recoilPx,\n    );\n    canvas.rotate(aimAngle);\n    if (!facingRight) {\n      canvas.scale(1, -1);\n    }\n\n    // Gun stock, receiver, barrel, and magazine\n    final Paint gunMetal = Paint()..color = const Color(0xFF1E293B);\n    final Paint gunHighlight = Paint()..color = const Color(0xFF64748B);\n    // Stock\n    canvas.drawRRect(\n      RRect.fromRectAndRadius(\n        const Rect.fromLTWH(-14, -3, 14, 7),\n        const Radius.circular(2),\n      ),\n      Paint()..color = const Color(0xFF451A03),\n    );\n    // Receiver body\n    canvas.drawRect(const Rect.fromLTWH(-2, -5, 22, 8), gunMetal);\n    canvas.drawRect(const Rect.fromLTWH(0, -4, 18, 2.5), gunHighlight);\n    // Curved banana magazine\n    final Path magPath = Path()\n      ..moveTo(6, 3)\n      ..lineTo(12, 3)\n      ..lineTo(15, 13)\n      ..lineTo(8, 13)\n      ..close();\n    canvas.drawPath(magPath, Paint()..color = const Color(0xFF0F172A));\n    // Heavy barrel + barrel shroud\n    canvas.drawRect(const Rect.fromLTWH(20, -4, 16, 4.5), gunMetal);\n    canvas.drawRect(\n      const Rect.fromLTWH(20, -5, 18, 9),\n      outline..strokeWidth = 1.6,\n    );\n\n    // Front hoof gripping the rifle handguard\n    canvas.drawCircle(\n      const Offset(14, 2),\n      4.2,\n      Paint()..color = darkHoof,\n    );\n\n    // Bright cartoon muzzle flash when firing\n    if (muzzleFlashTimer > 0) {\n      final Path flashPath = Path()\n        ..moveTo(36, -2)\n        ..lineTo(54, -10)\n        ..lineTo(47, -2)\n        ..lineTo(58, 0)\n        ..lineTo(47, 3)\n        ..lineTo(53, 10)\n        ..close();\n      canvas.drawPath(\n        flashPath,\n        Paint()..color = const Color(0xFFFef08a),\n      );\n      canvas.drawCircle(\n        const Offset(39, -1),\n        6,\n        Paint()..color = Colors.white,\n      );\n    }\n\n    canvas.restore();\n    canvas.restore();\n  }\n\n  void _drawBullets(Canvas canvas, Size size) {\n    for (final b in bullets) {\n      final Offset pos = Offset(b.x * size.width, b.y * size.height);\n      final double angle = atan2(b.vy, b.vx);\n      canvas.save();\n      canvas.translate(pos.dx, pos.dy);\n      canvas.rotate(angle);\n\n      // Glowing Contra energy/tracer shell\n      canvas.drawRRect(\n        RRect.fromRectAndRadius(\n          const Rect.fromLTWH(-9, -3.2, 18, 6.4),\n          const Radius.circular(3),\n        ),\n        Paint()..color = const Color(0xFFEF4444).withValues(alpha: 0.45),\n      );\n      canvas.drawRRect(\n        RRect.fromRectAndRadius(\n          const Rect.fromLTWH(-6, -2, 12, 4),\n          const Radius.circular(2),\n        ),\n        Paint()..color = const Color(0xFFFEF08A),\n      );\n      canvas.restore();\n    }\n  }\n\n  void _drawBloodParticles(Canvas canvas, Size size) {\n    for (final p in bloodParticles) {\n      final Offset pos = Offset(p.x * size.width, p.y * size.height);\n      final Paint bloodPaint = Paint()\n        ..color = (p.isChunk ? kDarkBlood : kCrimsonRed).withValues(\n          alpha: p.life.clamp(0.0, 1.0),\n        );\n      canvas.drawCircle(pos, p.radius, bloodPaint);\n    }\n  }\n\n  void _drawFloatingTexts(Canvas canvas, Size size) {\n    for (final ft in floatingTexts) {\n      final TextPainter tp = TextPainter(\n        text: TextSpan(\n          text: ft.text,\n          style: TextStyle(\n            color: ft.color.withValues(alpha: ft.life.clamp(0.0, 1.0)),\n            fontFamily: 'JetBrainsMono',\n            fontWeight: ft.isBold ? FontWeight.bold : FontWeight.w600,\n            fontSize: ft.isBold ? 14 : 12,\n            shadows: const [Shadow(color: Colors.black, blurRadius: 4)],\n          ),\n        ),\n        textDirection: TextDirection.ltr,\n      )..layout();\n\n      tp.paint(\n        canvas,\n        Offset(ft.x * size.width - tp.width / 2, ft.y * size.height),\n      );\n    }\n  }\n\n  void _drawSnowfall(Canvas canvas, Size size) {\n    final Paint snowPaint = Paint()\n      ..color = Colors.white.withValues(alpha: 0.78);\n    for (final f in snowflakes) {\n      canvas.drawCircle(\n        Offset(f.x * size.width, f.y * size.height),\n        f.radius,\n        snowPaint,\n      );\n    }\n  }\n\n  @override\n  bool shouldRepaint(covariant CustomPainter oldDelegate) => true;\n}\n\nclass _Platform {\n  final double xMin;\n  final double xMax;\n  final double y;\n\n  const _Platform({\n    required this.xMin,\n    required this.xMax,\n    required this.y,\n  });\n}\n\nclass _Bullet {\n  double x;\n  double y;\n  final double vx;\n  final double vy;\n\n  _Bullet({\n    required this.x,\n    required this.y,\n    required this.vx,\n    required this.vy,\n  });\n}\n\nclass _ReindeerTarget {\n  final String name;\n  double x;\n  double y;\n  final double baseY;\n  double vx;\n  double vy;\n  final bool isFlying;\n  int hp;\n  final int maxHp;\n  final int furVariant;\n  double legPhase;\n  double hitFlash = 0.0;\n  double panicTimer = 0.0;\n\n  _ReindeerTarget({\n    required this.name,\n    required this.x,\n    required this.y,\n    required this.vx,\n    required this.vy,\n    required this.isFlying,\n    required this.hp,\n    required this.maxHp,\n    required this.furVariant,\n    required this.legPhase,\n  }) : baseY = y;\n}\n\nclass _BloodParticle {\n  double x;\n  double y;\n  double vx;\n  double vy;\n  final double radius;\n  double life;\n  final bool isChunk;\n\n  _BloodParticle({\n    required this.x,\n    required this.y,\n    required this.vx,\n    required this.vy,\n    required this.radius,\n    required this.life,\n    this.isChunk = false,\n  });\n}\n\nclass _SnowStain {\n  final double x;\n  final double y;\n  final double radiusX;\n  final double radiusY;\n\n  _SnowStain({\n    required this.x,\n    required this.y,\n    required this.radiusX,\n    required this.radiusY,\n  });\n}\n\nclass _ShellCasing {\n  double x;\n  double y;\n  double vx;\n  double vy;\n  double rotation;\n\n  _ShellCasing({\n    required this.x,\n    required this.y,\n    required this.vx,\n    required this.vy,\n    required this.rotation,\n  });\n}\n\nclass _FloatingText {\n  final String text;\n  final double x;\n  double y;\n  final Color color;\n  double life;\n  final bool isBold;\n\n  _FloatingText({\n    required this.text,\n    required this.x,\n    required this.y,\n    required this.color,\n    required this.life,\n    this.isBold = false,\n  });\n}\n\nclass _HorizonCross {\n  final double x;\n  final double tilt;\n\n  _HorizonCross({required this.x, required this.tilt});\n}\n\nclass _Snowflake {\n  double x;\n  double y;\n  final double radius;\n  final double speedY;\n  final double drift;\n  final double phase;\n\n  _Snowflake({\n    required this.x,\n    required this.y,\n    required this.radius,\n    required this.speedY,\n    required this.drift,\n    required this.phase,\n  });\n}\n\nclass _Star {\n  final double x;\n  final double y;\n  final double size;\n  final double twinklePhase;\n\n  _Star({\n    required this.x,\n    required this.y,\n    required this.size,\n    required this.twinklePhase,\n  });\n}\n",
  "lib/games/gamepad_poller.dart": "import 'package:archbtw_sh/games/gamepad_poller_stub.dart'\n    if (dart.library.js_interop) 'package:archbtw_sh/games/gamepad_poller_web.dart';\n\nclass GamepadInputState {\n  final bool connected;\n  final String id;\n  final double axisX;\n  final double axisY;\n  final bool jumpPressed;\n  final bool punchPressed;\n  final bool kickPressed;\n  final bool chordPressed;\n  final bool webPressed;\n  final bool mountPressed;\n\n  const GamepadInputState({\n    this.connected = false,\n    this.id = '',\n    this.axisX = 0.0,\n    this.axisY = 0.0,\n    this.jumpPressed = false,\n    this.punchPressed = false,\n    this.kickPressed = false,\n    this.chordPressed = false,\n    this.webPressed = false,\n    this.mountPressed = false,\n  });\n\n  static const GamepadInputState disconnected = GamepadInputState();\n}\n\nGamepadInputState pollGamepadState() => pollBrowserGamepad();\n\nList<GamepadInputState> pollAllGamepads() => pollAllBrowserGamepads();\n\n\n",
