................', // 50\n    '..........KJJJJJK.................', // 51\n    '..........KSSSSsK.................', // 52: Exposed oval peach knee rip\n    '..........KSSsssK.................', // 53\n    '..........KcccccK.................', // 54: Knee shadow above combat boot top\n    '..........KJJJJJK.................', // 55: Upper Doc Martens boot shaft\n    '..........KJJJJJK.................', // 56\n    '..........KJJJJJK.................', // 57\n    '..........KJJJJJK.................', // 58\n    '..........KJJJJJK.................', // 59\n    '..........KJJJJJK.................', // 60\n    '..........KJJJJJK.................', // 61\n    '..........KJJJBKK.................', // 62: Boot ankle & horizontal lace bars\n    '..........KJJJBKK.................', // 63\n    '..........KJJKBBK.................', // 64\n    '..........KJJJBKK.................', // 65\n    '..........KJJBBKK.................', // 66\n    '..........KKBBBBKK................', // 67: Rounded Doc Martens toe box pointing right\n    '..........KKKBBBBK................', // 68\n    '..........KKKKKKKK................', // 69\n    '..........KKKKKKKK................', // 70: Chunky black lug sole\n    '...........KKKKKK.................', // 71\n    '...........KKKKKK.................', // 72\n    '............KKKK..................', // 73: Bottom sole flush with ground y=0\n  ];\n\n  static const List<String> player2RightLegMatrix = [\n    '...................KJJJJK.........', // 42: Upper thigh overlap inside pelvis\n    '...................KJJJJK.........', // 43\n    '...................KJJJJK.........', // 44\n    '...................KJJJJKK........', // 45: Ripped black denim jeans\n    '...................KJJJJJK........', // 46\n    '...................KJJJJJK........', // 47\n    '...................KJJJJJK........', // 48\n    '...................KJJJJJK........', // 49\n    '...................KJJJJJK........', // 50\n    '...................KJJJJJK........', // 51\n    '...................KccssKK........', // 52: Ripped knee slit\n    '...................KJJJJJK........', // 53\n    '...................KKKKKKK........', // 54\n    '...................KJJJJJK........', // 55: Upper Doc Martens boot shaft\n    '...................KJJJJJK........', // 56\n    '...................KJJJJJK........', // 57\n    '...................KJJJJJK........', // 58\n    '...................KJJJJJK........', // 59\n    '...................KJJJJJK........', // 60\n    '...................KJJJJJK........', // 61\n    '...................KBJJJKK........', // 62: Boot ankle & horizontal laces\n    '...................KBJJJKK........', // 63\n    '...................KBKJJKK........', // 64\n    '...................KBJJJKK........', // 65\n    '...................KBJJBBK........', // 66: Rounded Doc Martens toe box pointing right\n    '...................KKBBBBKK.......', // 67\n    '...................KKKBBBBK.......', // 68\n    '...................KKKKKKKK.......', // 69\n    '...................KKKKKKKK.......', // 70: Chunky black lug sole\n    '....................KKKKKK........', // 71\n    '....................KKKKKK........', // 72\n    '.....................KKKK.........', // 73: Bottom sole flush with ground y=0\n  ];\n\n  // Extended kicking right leg with ripped knee + black Doc Martens combat boot (25x7)\n  static const List<String> player2KickingRightLegMatrix = [\n    '................KKKKKK...', // 00: Combat boot collar & laces\n    'KKKKKKKKKKKKKKKKBJJBBKK..', // 01: Extended black jeans anchored to hip + boot shaft\n    'KJJJJJJSSsJJJJJKBKBBBBKK.', // 02: Black denim + exposed knee rip + boot toe highlight\n    'KJJJJJJSSsJJJJJKBKBBBBBK.', // 03: Black denim + knee rip + rounded Doc Martens toe\n    'KJJJJJJcccJJJJJKKKKKKKKK.', // 04: Jeans + chunky black lug outsole\n    '.KKKKKKKKKKKKKKK.........', // 05\n    '.........................', // 06\n  ];\n\n  void _drawCharacterSprite(\n    Canvas canvas,\n    OkcCharacterType character,\n    double sx,\n    double sy, {\n    required bool charFacingRight,\n    required double charWalkCycle,\n    required bool charIsGrounded,\n    required OkcAttackKind charAttack,\n    required double charAttackTimer,\n    required bool charHasGuitar,\n    required bool charHasSpiderPower,\n  }) {\n    const double px = 1.05; // Unified pixel density across all playable characters\n    final bool isPigeon = character == OkcCharacterType.pigeon;\n\n    // archBTW is 28x80 (~84 world units tall); Pigeon is 34x74 (~77.7 world units tall, slightly shorter)\n    final double spriteW = (isPigeon ? 34 : 28) * px;\n    final double upperH = (isPigeon ? 45 : 58) * px;\n    final double legH = (isPigeon ? 29 : 22) * px;\n    final double totalH = upperH + legH;\n\n    final Map<String, Color> palette =\n        isPigeon ? player2CharacterPalette : archBtwCharacterPalette;\n    final List<String> leftLeg =\n        isPigeon ? player2LeftLegMatrix : archBtwLeftLegMatrix;\n    final List<String> rightLeg =\n        isPigeon ? player2RightLegMatrix : archBtwRightLegMatrix;\n    final List<String> kickingLeg =\n        isPigeon ? player2KickingRightLegMatrix : archBtwKickingRightLegMatrix;\n    final List<String> upperBody =\n        isPigeon ? player2UpperBodyMatrix : archBtwUpperBodyMatrix;\n    final List<String> punchingUpperBody = isPigeon\n        ? player2PunchingUpperBodyMatrix\n        : archBtwPunchingUpperBodyMatrix;\n\n    final bool isMoving = charWalkCycle > 0 &&\n        ((charWalkCycle * 3.0).floor() % 4 == 1 ||\n            (charWalkCycle * 3.0).floor() % 4 == 3);\n    final int walkFrame = (charWalkCycle * 2.2).floor() % 4;\n    final bool isKicking =\n        charAttack == OkcAttackKind.kick && charAttackTimer > 0;\n    final bool isPunching =\n        charAttack == OkcAttackKind.punch && charAttackTimer > 0;\n\n    final double walkBob =\n        (charIsGrounded && isMoving) ? -px * 1.2 : 0.0;\n\n    canvas.save();\n    canvas.translate(sx, sy);\n    if (!charFacingRight) {\n      canvas.scale(-1.0, 1.0);\n    }\n\n    final Paint p = Paint()..isAntiAlias = false;\n\n    // 1. Draw Left & Right Legs (Pigeon's leg matrices include 3 overlap rows anchored into pelvis)\n    final double legStride = isPigeon ? px * 1.5 : px * 2.5;\n    final double legCross = isPigeon ? px * 0.9 : px * 2.5;\n    final double leftLegDx = !charIsGrounded\n        ? -px * 1.5\n        : (walkFrame == 1 ? -legStride : (walkFrame == 3 ? legCross : 0.0));\n    final double leftLegDy = !charIsGrounded\n        ? -px * 1.5\n        : (walkFrame == 1 ? -px * 1.5 : 0.0);\n    final double rightLegDx = !charIsGrounded\n        ? px * 1.5\n        : (walkFrame == 1 ? legStride : (walkFrame == 3 ? -legCross : 0.0));\n    final double rightLegDy = !charIsGrounded\n        ? -px * 1.0\n        : (walkFrame == 3 ? -px * 1.5 : 0.0);\n    final double legMatrixTopY = -leftLeg.length * px;\n\n    _drawPixelMatrix(\n      canvas,\n      leftLeg,\n      palette,\n      pixelSize: px,\n      origin: Offset(-spriteW / 2 + leftLegDx, legMatrixTopY + leftLegDy),\n    );\n\n    if (isKicking) {\n      _drawPixelMatrix(\n        canvas,\n        kickingLeg,\n        palette,\n        pixelSize: px,\n        origin: Offset(isPigeon ? 0.0 : px * 1, -legH + px * 1.5),\n      );\n    } else {\n      _drawPixelMatrix(\n        canvas,\n        rightLeg,\n        palette,\n        pixelSize: px,\n        origin: Offset(-spriteW / 2 + rightLegDx, legMatrixTopY + rightLegDy),\n      );\n    }\n\n    // 2. Draw Upper Body (switches to raised-arm punching pose when punching!)\n    _drawPixelMatrix(\n      canvas,\n      isPunching ? punchingUpperBody : upperBody,\n      palette,\n      pixelSize: px,\n      origin: Offset(-spriteW / 2, -totalH + walkBob),\n    );\n\n    // 3. Draw Equipped Detailed Purple PRS Custom 24 Electric Guitar\n    if (charHasGuitar) {\n      final bool isStrumming =\n          charAttack == OkcAttackKind.chord && charAttackTimer > 0;\n      final double gy =\n          -totalH + px * (isPigeon ? 36 : 44) + walkBob;\n      _drawPixelLine(\n        canvas,\n        Offset(-px * 3, -totalH + px * (isPigeon ? 21 : 27) + walkBob),\n        Offset(px * 4, gy),\n        pixelSize: px * 1.6,\n        color: Colors.black,\n      );\n      drawPurplePrsGuitar(\n        canvas,\n        Offset(px * 3, gy),\n        scale: px * 0.72,\n        angle: isStrumming ? -0.34 : -0.22,\n      );\n    }\n\n    // 4. Spider Web-Shooter Wrist Pixel Glow\n    if (charHasSpiderPower) {\n      p.color = const Color(0xFF3CBCFC);\n      canvas.drawRect(\n        Rect.fromLTWH(\n          px * 9,\n          -totalH + px * (isPigeon ? 40 : 48) + walkBob,\n          px * 3,\n          px * 3,\n        ),\n        p,\n      );\n    }\n\n    canvas.restore();\n  }\n\n  // --- Detailed 8-Bit Zombie Sprite ---\n  static const List<String> _zombieMatrix = [\n    '....KKKKKKKK....',\n    '...KGGGGGGGGK...',\n    '..KGGGGGGGGGGK..',\n    '..KGGRRGGGRRGK..', // Glowing red zombie eyes\n    '..KGGGGGGGGGGK..',\n    '...KGGKKKKGGK...',\n    '....KKKKKKKK....',\n    '..KKCCCCCCCCKKKK',\n    '.KCCCRRRRRCCCGGG', // Exposed ribs + outstretched zombie arms\n    '.KCCCCCCCCCCCGGG',\n    '.KCCCRRRRRCCCKKK',\n    '..KKCCCCCCCCKK..',\n    '...KPPPPPPPPK...',\n    '...KPPK..KPPK...',\n    '...KPPK..KPPK...',\n    '...KKKK..KKKK...',\n  ];\n\n  void _drawZombie(Canvas canvas, OkcZombie z, double sx, double sy) {\n    final double px = z.kind == OkcZombieKind.brute ? 3.8 : 3.0;\n    final double w = 16 * px;\n    final double h = 16 * px;\n    final double shambleBob = ((z.walkPhase * 1.5).floor() % 2) * 3.0;\n\n    final Color skinColor = z.hurtTimer > 0\n        ? Colors.white\n        : (z.kind == OkcZombieKind.runner\n            ? const Color(0xFF84CC16)\n            : const Color(0xFF58F898));\n    final Color coatColor = z.kind == OkcZombieKind.brute\n        ? const Color(0xFF581C87)\n        : const Color(0xFF334155);\n\n    canvas.save();\n    canvas.translate(sx, sy - shambleBob);\n    if (!z.facingRight) {\n      canvas.scale(-1.0, 1.0);\n    }\n\n    _drawPixelMatrix(\n      canvas,\n      _zombieMatrix,\n      {\n        'K': Colors.black,\n        'G': skinColor,\n        'R': const Color(0xFFF83870), // Red eyes & ribs\n        'C': coatColor,\n        'P': const Color(0xFF1E293B),\n      },\n      pixelSize: px,\n      origin: Offset(-w / 2, -h),\n    );\n\n    canvas.restore();\n\n    // 8-Bit Pixel Zombie HP Bar\n    if (z.hp < z.maxHp) {\n      final double frac = (z.hp / z.maxHp).clamp(0.0, 1.0);\n      final Paint p = Paint()..isAntiAlias = false;\n      p.color = Colors.black;\n      canvas.drawRect(Rect.fromLTWH(sx - 18, sy - h - 12, 36, 7), p);\n      p.color = const Color(0xFFF83870);\n      canvas.drawRect(Rect.fromLTWH(sx - 16, sy - h - 10, 32 * frac, 3), p);\n    }\n  }\n\n  // --- Detailed 8-Bit Powerups: Pills, Guitar, Spider ---\n  static const List<String> _pillMatrix = [\n    '..KKKKKKKKKK..',\n    '.KRRRRRWWWWWK.',\n    'KRRRRRRWWWWWWK',\n    'KRRRRRRWWWWWWK',\n    '.KRRRRRWWWWWK.',\n    '..KKKKKKKKKK..',\n  ];\n\n  static const List<String> _spiderMatrix = [\n    'K..K..KKKK..K..K',\n    '.K.K.KRRRRK.K.K.',\n    '..KKKRRRRRRKKK..',\n    '....KRWWWWWRK...',\n    '..KKKRRRRRRKKK..',\n    '.K.K.KRRRRK.K.K.',\n    'K..K..KKKK..K..K',\n  ];\n\n  void _drawPowerupItem(\n    Canvas canvas,\n    OkcPowerupItem item,\n    double sx,\n    double sy,\n  ) {\n    const double px = 2.8;\n    switch (item.type) {\n      case OkcPowerupType.pill:\n        _drawPixelMatrix(\n          canvas,\n          _pillMatrix,\n          const {\n            'K': Colors.black,\n            'R': Color(0xFFF83870),\n            'W': Colors.white,\n          },\n          pixelSize: px,\n          origin: Offset(sx - 7 * px, sy - 3 * px),\n        );\n        _drawLabel(\n          canvas,\n          '+HP PILL',\n          Offset(sx, sy - 18),\n          const Color(0xFF58F898),\n          fontSize: 10,\n          bold: true,\n        );\n        break;\n\n      case OkcPowerupType.guitar:\n        drawPurplePrsGuitar(\n          canvas,\n          Offset(sx - 4, sy + 2),\n          scale: 0.90,\n          angle: -0.58,\n        );\n        _drawLabel(\n          canvas,\n          'PURPLE PRS [CHORDS]',\n          Offset(sx, sy - 28),\n          const Color(0xFFB878F8),\n          fontSize: 10,\n          bold: true,\n        );\n        break;\n\n      case OkcPowerupType.spider:\n        _drawPixelMatrix(\n          canvas,\n          _spiderMatrix,\n          const {\n            'K': Color(0xFF3CBCFC),\n            'R': Color(0xFFF83870),\n            'W': Colors.white,\n          },\n          pixelSize: px,\n          origin: Offset(sx - 8 * px, sy - 3.5 * px),\n        );\n        _drawLabel(\n          canvas,\n          'SPIDER [WEB]',\n          Offset(sx, sy - 22),\n          const Color(0xFF3CBCFC),\n          fontSize: 10,\n          bold: true,\n        );\n        break;\n    }\n  }\n\n  void _drawChordProjectile(\n    Canvas canvas,\n    OkcChordProjectile chord,\n    double sx,\n    double sy,\n  ) {\n    final Paint p = Paint()..isAntiAlias = false;\n    const double px = 1.5;\n    final double phase = worldTime * 24.0 + chord.x * 0.08;\n\n    canvas.save();\n    canvas.translate(sx, sy);\n    if (chord.vx < 0) {\n      canvas.scale(-1.0, 1.0);\n    }\n\n    // 1. Oscillating Audio Waveform / Equalizer Bars in the Wake (x: -22..+2)\n    const int barCount = 9;\n    for (int i = 0; i < barCount; i++) {\n      final double t = (i + 1) / barCount; // 0..1 from tail to front\n      final double bx = -22.0 + i * 3.0;\n      final double wave = (0.45 + 0.55 * sin(phase - i * 0.85).abs()) * t;\n      final double halfH = (2.0 + wave * 11.0).floorToDouble();\n\n      // 1px black pixel outline around each waveform bar\n      p.color = const Color(0xFF020103);\n      canvas.drawRect(\n        Rect.fromLTWH(bx - 1, -halfH - 1, 4.0, halfH * 2 + 2.0),\n        p,\n      );\n      // Colored harmonic bar body\n      p.color = chord.color;\n      canvas.drawRect(\n        Rect.fromLTWH(bx, -halfH, 2.0, halfH * 2),\n        p,\n      );\n      // Bright white center audio axis core\n      p.color = Colors.white;\n      canvas.drawRect(\n        Rect.fromLTWH(bx, -halfH * 0.35, 2.0, max(2.0, halfH * 0.7)),\n        p,\n      );\n    }\n\n    // 2. Three Concentric Propagating Sonic Wavefront Arcs \")))\" (x: +3..+20)\n    // Drawn as stepped pixel-art crescent arcs curving forward in the direction of travel\n    for (int arcIdx = 0; arcIdx < 3; arcIdx++) {\n      final double baseX = 3.0 + arcIdx * 6.0;\n      final int halfSteps = 4 + arcIdx * 2; // 4, 6, 8 pixel steps above & below y=0\n      final bool isLeadingArc = arcIdx == 2;\n\n      // Pass 1: Black pixel outline behind the sonic arc\n      p.color = const Color(0xFF020103);\n      for (int s = -halfSteps; s <= halfSteps; s++) {\n        final double norm = s.abs() / halfSteps;\n        final double curveOffset =\n            ((1.0 - norm * norm) * (3.5 + arcIdx * 1.2)).floorToDouble();\n        final double ax = baseX + curveOffset;\n        final double ay = s * px * 1.35;\n        canvas.drawRect(\n          Rect.fromCenter(\n            center: Offset(ax, ay),\n            width: px * 2.8,\n            height: px * 2.4,\n          ),\n          p,\n        );\n      }\n\n      // Pass 2: Vibrant neon soundwave arc body + white leading-edge highlight\n      for (int s = -halfSteps; s <= halfSteps; s++) {\n        final double norm = s.abs() / halfSteps;\n        final double curveOffset =\n            ((1.0 - norm * norm) * (3.5 + arcIdx * 1.2)).floorToDouble();\n        final double ax = baseX + curveOffset;\n        final double ay = s * px * 1.35;\n\n        p.color = chord.color;\n        canvas.drawRect(\n          Rect.fromCenter(\n            center: Offset(ax, ay),\n            width: px * 1.7,\n            height: px * 1.5,\n          ),\n          p,\n        );\n        if (s.abs() <= halfSteps - 2 || isLeadingArc) {\n          p.color = Colors.white;\n          canvas.drawRect(\n            Rect.fromCenter(\n              center: Offset(ax + px * 0.35, ay),\n              width: px * 0.8,\n              height: px * 1.1,\n            ),\n            p,\n          );\n        }\n      }\n    }\n\n    canvas.restore();\n  }\n\n  void _drawNesBannerLabel(\n    Canvas canvas,\n    String text,\n    Offset center,\n    Color color, {\n    double fontSize = 10,\n  }) {\n    _drawLabel(\n      canvas,\n      text,\n      center,\n      color,\n      fontSize: fontSize,\n      bold: true,\n    );\n  }\n\n  void _drawLabel(\n    Canvas canvas,\n    String text,\n    Offset center,\n    Color color, {\n    double fontSize = 10,\n    bool bold = false,\n  }) {\n    final TextPainter tp = TextPainter(\n      text: TextSpan(\n        text: text,\n        style: TextStyle(\n          color: color,\n          fontFamily: 'JetBrainsMono',\n          fontSize: fontSize,\n          fontWeight: bold ? FontWeight.bold : FontWeight.normal,\n          shadows: const [\n            Shadow(color: Colors.black, blurRadius: 0, offset: Offset(1.5, 1.5)),\n          ],\n        ),\n      ),\n      textDirection: TextDirection.ltr,\n    )..layout();\n    tp.paint(canvas, center - Offset(tp.width / 2, tp.height / 2));\n  }\n\n  @override\n  bool shouldRepaint(covariant _OkcRetroGamePainter oldDelegate) => true;\n}\n\n// --- Title Screen Hero Showcase Painter (archBTW + Player 2 + Purple PRS Custom 24) ---\nclass _SuperArchBtwTitleHeroPainter extends CustomPainter {\n  final double worldTime;\n  final OkcCharacterType selectedCharacter;\n  final int playerCount;\n\n  _SuperArchBtwTitleHeroPainter({\n    required this.worldTime,\n    required this.selectedCharacter,\n    required this.playerCount,\n  });\n\n  void _drawMatrix(\n    Canvas canvas,\n    List<String> rows,\n    Map<String, Color> palette, {\n    required double pixelSize,\n    required Offset origin,\n  }) {\n    final Paint p = Paint()..isAntiAlias = false;\n    for (int r = 0; r < rows.length; r++) {\n      final String row = rows[r];\n      int c = 0;\n      while (c < row.length) {\n        final String ch = row[c];\n        final Color? color = palette[ch];\n        if (color == null) {\n          c++;\n          continue;\n        }\n        int run = 1;\n        while (c + run < row.length && row[c + run] == ch) {\n          run++;\n        }\n        p.color = color;\n        canvas.drawRect(\n          Rect.fromLTWH(\n            origin.dx + c * pixelSize,\n            origin.dy + r * pixelSize,\n            run * pixelSize,\n            pixelSize,\n          ),\n          p,\n        );\n        c += run;\n      }\n    }\n  }\n\n  @override\n  void paint(Canvas canvas, Size size) {\n    final Paint p = Paint()..isAntiAlias = false;\n\n    // Retro stage floor pedestal\n    final double floorY = size.height - 10;\n    p.color = const Color(0xFF33134F);\n    canvas.drawRect(Rect.fromLTWH(16, floorY, size.width - 32, 6), p);\n    p.color = const Color(0xFFB878F8);\n    canvas.drawRect(Rect.fromLTWH(24, floorY, size.width - 48, 2), p);\n\n    final double charPx = (size.height - 20) / 80.0;\n\n    // 1. Draw the 28x80 archBTW character sprite on the left side of the stage\n    final double archW = 28 * charPx;\n    final double archX = size.width * 0.23 - archW / 2;\n    final double archTopY = floorY - 80 * charPx;\n    final bool archActive =\n        playerCount == 2 || selectedCharacter == OkcCharacterType.archBtw;\n\n    if (archActive) {\n      p.color = const Color(0xFFB878F8).withValues(alpha: 0.28);\n      canvas.drawRect(\n        Rect.fromLTWH(archX - 4, floorY - 4, archW + 8, 6),\n        p,\n      );\n    }\n\n    _drawMatrix(\n      canvas,\n      _OkcRetroGamePainter.archBtwLeftLegMatrix,\n      _OkcRetroGamePainter.archBtwCharacterPalette,\n      pixelSize: charPx,\n      origin: Offset(archX, archTopY + 58 * charPx),\n    );\n    _drawMatrix(\n      canvas,\n      _OkcRetroGamePainter.archBtwRightLegMatrix,\n      _OkcRetroGamePainter.archBtwCharacterPalette,\n      pixelSize: charPx,\n      origin: Offset(archX, archTopY + 58 * charPx),\n    );\n    _drawMatrix(\n      canvas,\n      _OkcRetroGamePainter.archBtwUpperBodyMatrix,\n      _OkcRetroGamePainter.archBtwCharacterPalette,\n      pixelSize: charPx,\n      origin: Offset(archX, archTopY),\n    );\n\n    // 2. Draw the 34x74 Pigeon playable character (slightly shorter than archBTW!) in the center\n    final double p2W = 34 * charPx;\n    final double p2X = size.width * 0.50 - p2W / 2;\n    final double p2TopY = floorY - 74 * charPx;\n    final bool p2Active =\n        playerCount == 2 || selectedCharacter == OkcCharacterType.pigeon;\n\n    if (p2Active) {\n      p.color = const Color(0xFF3CBCFC).withValues(alpha: 0.28);\n      canvas.drawRect(\n        Rect.fromLTWH(p2X - 4, floorY - 4, p2W + 8, 6),\n        p,\n      );\n    }\n\n    _drawMatrix(\n      canvas,\n      _OkcRetroGamePainter.player2LeftLegMatrix,\n      _OkcRetroGamePainter.player2CharacterPalette,\n      pixelSize: charPx,\n      origin: Offset(p2X, p2TopY + 42 * charPx),\n    );\n    _drawMatrix(\n      canvas,\n      _OkcRetroGamePainter.player2RightLegMatrix,\n      _OkcRetroGamePainter.player2CharacterPalette,\n      pixelSize: charPx,\n      origin: Offset(p2X, p2TopY + 42 * charPx),\n    );\n    _drawMatrix(\n      canvas,\n      _OkcRetroGamePainter.player2UpperBodyMatrix,\n      _OkcRetroGamePainter.player2CharacterPalette,\n      pixelSize: charPx,\n      origin: Offset(p2X, p2TopY),\n    );\n\n    // 3. Draw the detailed Purple PRS Custom 24 showcase on the right side of the stage\n    final double bob = sin(worldTime * 3.5) * 3.5;\n    final double gx = size.width * 0.78;\n    final double gy = size.height * 0.54 + bob;\n\n    _OkcRetroGamePainter.drawPurplePrsGuitar(\n      canvas,\n      Offset(gx, gy),\n      scale: charPx * 1.15,\n      angle: -0.62,\n    );\n  }\n\n  @override\n  bool shouldRepaint(covariant _SuperArchBtwTitleHeroPainter oldDelegate) =>\n      oldDelegate.worldTime != worldTime ||\n      oldDelegate.selectedCharacter != selectedCharacter ||\n      oldDelegate.playerCount != playerCount;\n}\n",
  "lib/global/helpers.dart": "import 'package:flutter/material.dart';\nimport 'package:url_launcher/url_launcher.dart';\n\nFuture<void> openUrl(String url) async {\n  final Uri uri = Uri.parse(url);\n  if (!await launchUrl(\n    uri,\n    mode: LaunchMode.externalApplication,\n    webOnlyWindowName: '_blank',\n  )) {\n    debugPrint('Could not launch \$url');\n  }\n}\n\n",
  "lib/global/noop_url_strategy.dart": "void usePathUrlStrategy() {}\n",
  "lib/global/site_music_controller.dart": "import 'dart:async';\nimport 'package:archbtw_sh/widgets/in_game_music_hud.dart';\nimport 'package:audioplayers/audioplayers.dart';\nimport 'package:flutter/foundation.dart';\n\nclass SiteMusicController extends ChangeNotifier {\n  SiteMusicController._();\n  static final SiteMusicController instance = SiteMusicController._();\n\n  AudioPlayer? _audioPlayer;\n  StreamSubscription? _durationSubscription;\n  StreamSubscription? _positionSubscription;\n  StreamSubscription? _playerCompleteSubscription;\n  StreamSubscription? _playerStateSubscription;\n\n  String? _albumTitle;\n  String? _audioPath;\n  List<String> _tracks = const [];\n  int _currentTrackIndex = 0;\n  bool _isPlaying = false;\n  bool _hasActiveSession = false;\n  Duration _duration = Duration.zero;\n  Duration _position = Duration.zero;\n\n  final List<String> _visibleAlbumPaths = [];\n  int _activeGameCount = 0;\n\n  String? get albumTitle => _albumTitle;\n  String? get audioPath => _audioPath;\n  List<String> get tracks => _tracks;\n  int get currentTrackIndex => _currentTrackIndex;\n  bool get isPlaying => _isPlaying;\n  bool get hasActiveSession => _hasActiveSession && _tracks.isNotEmpty;\n  Duration get duration => _duration;\n  Duration get position => _position;\n\n  String get currentTrackName {\n    if (_tracks.isEmpty) return '';\n    final idx = _currentTrackIndex.clamp(0, _tracks.length - 1);\n    return _tracks[idx];\n  }\n\n  bool isAlbumLoaded(String audioPath) =>\n      _hasActiveSession && _audioPath == audioPath;\n\n  /// Show the floating toast when a track session is active, the user is not\n  /// inside a full-screen game, and the user is not currently viewing the\n  /// AlbumDetailPage for the active album.\n  bool get shouldShowFloatingToast {\n    if (!hasActiveSession || _activeGameCount > 0) return false;\n    final currentVisible = _visibleAlbumPaths.isNotEmpty\n        ? _visibleAlbumPaths.last\n        : null;\n    return currentVisible != _audioPath;\n  }\n\n  void registerVisibleAlbum(String audioPath) {\n    _visibleAlbumPaths.add(audioPath);\n    WidgetsBindingFlush.scheduleNotify(notifyListeners);\n  }\n\n  void unregisterVisibleAlbum(String audioPath) {\n    _visibleAlbumPaths.remove(audioPath);\n    WidgetsBindingFlush.scheduleNotify(notifyListeners);\n  }\n\n  void enterGame() {\n    _activeGameCount++;\n    if (_isPlaying) {\n      pause();\n    } else {\n      WidgetsBindingFlush.scheduleNotify(notifyListeners);\n    }\n  }\n\n  void exitGame() {\n    if (_activeGameCount > 0) {\n      _activeGameCount--;\n    }\n    WidgetsBindingFlush.scheduleNotify(notifyListeners);\n  }\n\n  AudioPlayer _ensurePlayer() {\n    if (_audioPlayer != null) return _audioPlayer!;\n    configureBackgroundAudioContext();\n    final player = AudioPlayer();\n    _audioPlayer = player;\n\n    _durationSubscription = player.onDurationChanged.listen((d) {\n      _duration = d;\n      notifyListeners();\n    });\n\n    _positionSubscription = player.onPositionChanged.listen((p) {\n      _position = p;\n      notifyListeners();\n    });\n\n    _playerCompleteSubscription = player.onPlayerComplete.listen((_) {\n      next();\n    });\n\n    _playerStateSubscription = player.onPlayerStateChanged.listen((state) {\n      _isPlaying = state == PlayerState.playing;\n      notifyListeners();\n    });\n\n    return player;\n  }\n\n  Future<void> playAlbumTrack({\n    required String albumTitle,\n    required String audioPath,\n    required List<String> tracks,\n    required int trackIndex,\n  }) async {\n    if (tracks.isEmpty) return;\n    _albumTitle = albumTitle;\n    _audioPath = audioPath;\n    _tracks = List<String>.unmodifiable(tracks);\n    _currentTrackIndex =\n        (trackIndex % _tracks.length + _tracks.length) % _tracks.length;\n    _hasActiveSession = true;\n    _isPlaying = true;\n    _position = Duration.zero;\n    _duration = Duration.zero;\n    notifyListeners();\n\n    try {\n      final player = _ensurePlayer();\n      final track = _tracks[_currentTrackIndex];\n      await player.play(AssetSource('\$_audioPath\$track'));\n      final d = await player.getDuration();\n      if (d != null && d > Duration.zero) {\n        _duration = d;\n        notifyListeners();\n      }\n    } catch (e) {\n      debugPrint('SiteMusicController play error: \$e');\n    }\n  }\n\n  Future<void> togglePlayPause({\n    String? albumTitle,\n    String? audioPath,\n    List<String>? tracks,\n    int? selectedIndex,\n  }) async {\n    // If toggling from an album that isn't currently loaded, load and play it\n    if (audioPath != null &&\n        tracks != null &&\n        tracks.isNotEmpty &&\n        (!_hasActiveSession || _audioPath != audioPath)) {\n      await playAlbumTrack(\n        albumTitle: albumTitle ?? '',\n        audioPath: audioPath,\n        tracks: tracks,\n        trackIndex: selectedIndex ?? 0,\n      );\n      return;\n    }\n\n    if (!_hasActiveSession || _tracks.isEmpty) return;\n\n    if (_isPlaying) {\n      await pause();\n    } else {\n      await resume();\n    }\n  }\n\n  Future<void> pause() async {\n    _isPlaying = false;\n    notifyListeners();\n    try {\n      await _audioPlayer?.pause();\n    } catch (e) {\n      debugPrint('SiteMusicController pause error: \$e');\n    }\n  }\n\n  Future<void> resume() async {\n    if (_tracks.isEmpty || _audioPath == null) return;\n    _isPlaying = true;\n    _hasActiveSession = true;\n    notifyListeners();\n    try {\n      final player = _ensurePlayer();\n      if (_position == Duration.zero) {\n        final track = _tracks[_currentTrackIndex];\n        await player.play(AssetSource('\$_audioPath\$track'));\n      } else {\n        await player.resume();\n      }\n    } catch (e) {\n      debugPrint('SiteMusicController resume error: \$e');\n    }\n  }\n\n  Future<void> next({\n    String? albumTitle,\n    String? audioPath,\n    List<String>? tracks,\n  }) async {\n    if (audioPath != null &&\n        tracks != null &&\n        tracks.isNotEmpty &&\n        (!_hasActiveSession || _audioPath != audioPath)) {\n      await playAlbumTrack(\n        albumTitle: albumTitle ?? '',\n        audioPath: audioPath,\n        tracks: tracks,\n        trackIndex: 1 % tracks.length,\n      );\n      return;\n    }\n    if (_tracks.isEmpty || _audioPath == null) return;\n    final nextIdx = (_currentTrackIndex + 1) % _tracks.length;\n    await playAlbumTrack(\n      albumTitle: _albumTitle ?? '',\n      audioPath: _audioPath!,\n      tracks: _tracks,\n      trackIndex: nextIdx,\n    );\n  }\n\n  Future<void> previous({\n    String? albumTitle,\n    String? audioPath,\n    List<String>? tracks,\n  }) async {\n    if (audioPath != null &&\n        tracks != null &&\n        tracks.isNotEmpty &&\n        (!_hasActiveSession || _audioPath != audioPath)) {\n      await playAlbumTrack(\n        albumTitle: albumTitle ?? '',\n        audioPath: audioPath,\n        tracks: tracks,\n        trackIndex: (tracks.length - 1) % tracks.length,\n      );\n      return;\n    }\n    if (_tracks.isEmpty || _audioPath == null) return;\n    final prevIdx = (_currentTrackIndex - 1 + _tracks.length) % _tracks.length;\n    await playAlbumTrack(\n      albumTitle: _albumTitle ?? '',\n      audioPath: _audioPath!,\n      tracks: _tracks,\n      trackIndex: prevIdx,\n    );\n  }\n\n  Future<void> seek(Duration target) async {\n    _position = target;\n    notifyListeners();\n    try {\n      await _audioPlayer?.seek(target);\n    } catch (e) {\n      debugPrint('SiteMusicController seek error: \$e');\n    }\n  }\n\n  Future<void> stopAndDismiss() async {\n    _isPlaying = false;\n    _hasActiveSession = false;\n    _position = Duration.zero;\n    notifyListeners();\n    try {\n      await _audioPlayer?.stop();\n    } catch (e) {\n      debugPrint('SiteMusicController stop error: \$e');\n    }\n  }\n\n  @visibleForTesting\n  void resetForTest() {\n    _durationSubscription?.cancel();\n    _positionSubscription?.cancel();\n    _playerCompleteSubscription?.cancel();\n    _playerStateSubscription?.cancel();\n    _audioPlayer?.dispose();\n    _audioPlayer = null;\n    _albumTitle = null;\n    _audioPath = null;\n    _tracks = const [];\n    _currentTrackIndex = 0;\n    _isPlaying = false;\n    _hasActiveSession = false;\n    _duration = Duration.zero;\n    _position = Duration.zero;\n    _visibleAlbumPaths.clear();\n    _activeGameCount = 0;\n  }\n}\n\nclass WidgetsBindingFlush {\n  static void scheduleNotify(VoidCallback callback) {\n    Future.microtask(callback);\n  }\n}\n\n",
  "lib/global/colors.dart": "import 'package:flutter/material.dart';\n\nconst Color kTerminalGreen = Colors.white;\nconst Color kTerminalDark = Color(0xFF0A1A0A);\nconst Color kBackgroundColor = Colors.black;\nconst Color kTextColor = Colors.white;\nconst Color kAccentColor = Color(0xFFB072FF);\n\n// Subtle holiday terminal accent palette\nconst Color kHolidayRed = Color(0xFFE05A6D);\nconst Color kHolidayGreen = Color(0xFF56B682);\nconst Color kHolidayGold = Color(0xFFE5C07B);\nconst Color kHolidayIce = Color(0xFF88C0D0);\n\n",
  "lib/pages/about/about.dart": "import 'package:archbtw_sh/global/colors.dart';\nimport 'package:flutter/material.dart';\n\nclass AboutPage extends StatelessWidget {\n  const AboutPage({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    final bool isDesktop = MediaQuery.of(context).size.width >= 768.0;\n    final EdgeInsets padding = isDesktop\n        ? const EdgeInsets.symmetric(horizontal: 120.0, vertical: 48.0)\n        : const EdgeInsets.symmetric(horizontal: 24.0, vertical: 24.0);\n\n    final baseStyle = TextStyle(\n      color: kTextColor,\n      fontSize: isDesktop ? 16 : 14,\n      height: 1.6,\n      fontFamily: 'JetBrainsMono',\n    );\n\n    const Color santaRed = Color(0xFFE53935);\n    const Color santaWhite = Colors.white;\n\n    return SingleChildScrollView(\n      padding: padding,\n      child: Center(\n        child: ConstrainedBox(\n          constraints: const BoxConstraints(maxWidth: 800),\n          child: Column(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              Text.rich(\n                TextSpan(\n                  style: baseStyle,\n                  children: const [\n                    TextSpan(\n                      text: \" __________________\\n\"\n                          \"< hi. i'm archBTW. >\\n\"\n                          \" ------------------\\n\"\n                          \"       \\\\     \",\n                    ),\n                    TextSpan(\n                      text: \"*\\n\",\n                      style: TextStyle(\n                        color: santaWhite,\n                        fontWeight: FontWeight.bold,\n                      ),\n                    ),\n                    TextSpan(text: \"        \\\\   \"),\n                    TextSpan(\n                      text: \"/.\\\\\\n\",\n                      style: TextStyle(\n                        color: santaRed,\n                        fontWeight: FontWeight.bold,\n                      ),\n                    ),\n                    TextSpan(text: \"         \\\\ \"),\n                    TextSpan(\n                      text: \"/...\\\\\\n\",\n                      style: TextStyle(\n                        color: santaRed,\n                        fontWeight: FontWeight.bold,\n                      ),\n                    ),\n                    TextSpan(text: \"          \"),\n                    TextSpan(\n                      text: \"(=====)\\n\",\n                      style: TextStyle(\n                        color: santaWhite,\n                        fontWeight: FontWeight.bold,\n                      ),\n                    ),\n                    TextSpan(\n                      text: \"            ^__^\\n\"\n                          \"            (oo)\\\\_______\\n\"\n                          \"            (__)\\\\       )\\\\/\\\\\\n\"\n                          \"                ||----w |\\n\"\n                          \"                ||     ||\\n\\n\\n\"\n                          \"I started this project at the beginning of 2024 as a sort of musical diary. I've played guitar since I was a kid and started writing music in 5th grade. This continued into my later years, writing acoustic songs since I didn't have a band or know how to use music software. For several years, I was even a soundcloud rapper. As cringe as that was, it did teach me a lot about writing and using software so archBTW wouldn't exist without that experience.\\n\\n\"\n                          \"archBTW has been my way of combining the emo confessionals I grew up with and the stream-of-consciousness hip hop that I fell in love with in my 20's. All wrapped in a bedroom-indie package. \\n\\n\"\n                          \"I write and produce all of my music myself from the guitar and bass down to the synths and drums. I'm a huge fan of bandlab for this (it's way better and more capable than people think). I play a modded purple Harley Benton PRS-style guitar mainly but also have an SG, Tele, Mitchell acoustic, and occasionally borrow a strat. \\n\\n\"\n                          \"All of the guitar sounds you hear come from various pedals (the main 2 being a fender amp simulator and a ts-808 clone) sometimes mixed with some digital effects depending on the song. \\n\\n\"\n                          \"More background on me as a person:\\n\\n\"\n                          \"My name is Archer and I live in Oklahoma City with my wife, dog, cat, and bearded dragon. When I'm not writing and making music, I'm working as a DevOps Engineer or coding on my personal projects. Before DevOps, I worked as a software developer and before that, as a systems administrator so DevOps has been a fun way to combine the two worlds.\\n\\n\"\n                          \"Coding and music are huge passions of mine, but aside from those, I'm also a pretty big gearhead, a theology nerd, and a huge Linux fanboy.\\n\\n\"\n                          \"Oh, I also have a mild obsession with Sanrio, specifically My Melody.\\n\\n\"\n                          \"If you'd like to know more, click on the music tab. Like I said, it's pretty much my diary.\\n\\n\"\n                          \"-archBTW\\n\\n\",\n                    ),\n                  ],\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}\n",
  "lib/pages/error/kernel_panic_page.dart": "import 'dart:async';\nimport 'dart:math';\nimport 'package:archbtw_sh/global/colors.dart';\nimport 'package:flutter/material.dart';\n\nclass KernelPanicPage extends StatefulWidget {\n  const KernelPanicPage({super.key});\n\n  @override\n  State<KernelPanicPage> createState() => _KernelPanicPageState();\n}\n\nclass _KernelPanicPageState extends State<KernelPanicPage> {\n  final List<String> _lines = [];\n  final ScrollController _scrollController = ScrollController();\n  bool _isPanic = false;\n  Timer? _timer;\n  int _lineIndex = 0;\n\n  final List<String> _panicLogs = [\n    \"[    0.000000] Linux version 6.8.0-archbtw (gcc version 13.2.1) #1 SMP PREEMPT_DYNAMIC\",\n    \"[    0.000000] Command line: initrd=\\\\initramfs-linux.img root=PARTUUID=deadbeef-01 rw quiet\",\n    \"[    0.000000] x86/fpu: Supporting XSAVE feature 0x001: 'x87 floating point registers'\",\n    \"[    0.000000] x86/fpu: Supporting XSAVE feature 0x002: 'SSE registers'\",\n    \"[    0.000000] x86/fpu: Supporting XSAVE feature 0x004: 'AVX registers'\",\n    \"[    0.000000] BIOS-e820: [mem 0x0000000000000000-0x000000000009ffff] usable\",\n    \"[    0.000000] BIOS-e820: [mem 0x0000000000100000-0x00000000bfffffff] usable\",\n    \"[    0.000001] NX (Execute Disable) protection: active\",\n    \"[    0.000002] SMBIOS 3.5.0 present.\",\n    \"[    0.000123] DMI: archBTW Virtual Machine/archBTW-VM, BIOS 1.16.2-1.fc38 04/01/2014\",\n    \"[    0.001456] tsc: Fast TSC calibration failed\",\n    \"[    0.012345] Calibrating delay loop... 5988.12 BogoMIPS (lpj=2994060)\",\n    \"[    0.123456] devtmpfs: initialized\",\n    \"[    0.234567] clocksource: jiffies: mask: 0xffffffff max_cycles: 0xffffffff, max_idle_ns: 7645041785100000 ns\",\n    \"[    0.345678] NET: Registered Data Link Protocol family 0\",\n    \"[    0.456789] Storage device found: /dev/sda1 (ext4)\",\n    \"[    0.567890] EXT4-fs (sda1): mounting root file system\",\n    \"[    0.678901] EXT4-fs (sda1): ERROR: unexpected journal error -5\",\n    \"[    0.789012] EXT4-fs (sda1): critical error: cannot read superblock\",\n    \"[    0.890123] Kernel panic - not syncing: VFS: Unable to mount root fs on unknown-block(0,0)\",\n    \"[    0.890124] CPU: 0 PID: 1 Comm: swapper/0 Not tainted 6.8.0-archbtw #1\",\n    \"[    0.890125] Hardware name: archBTW Virtual Machine\",\n    \"[    0.890126] Call Trace:\",\n    \"[    0.890127]  <TASK>\",\n    \"[    0.890128]  dump_stack_lvl+0x44/0x5c\",\n    \"[    0.890129]  panic+0x10d/0x2ad\",\n    \"[    0.890130]  mount_block_root+0x1a8/0x1b4\",\n    \"[    0.890131]  mount_root+0x6e/0x81\",\n    \"[    0.890132]  prepare_namespace+0x13b/0x182\",\n    \"[    0.890133]  kernel_init_freeable+0x231/0x256\",\n    \"[    0.890134]  ? rest_init+0xce/0xce\",\n    \"[    0.890135]  kernel_init+0x17/0x130\",\n    \"[    0.890136]  ret_from_fork+0x1f/0x30\",\n    \"[    0.890137]  </TASK>\",\n    \"[    0.890138] ---[ end Kernel panic - not syncing: VFS: Unable to mount root fs on unknown-block(0,0) ]---\",\n  ];\n\n  @override\n  void initState() {\n    super.initState();\n    _startBootSequence();\n  }\n\n  void _startBootSequence() {\n    _timer = Timer.periodic(const Duration(milliseconds: 50), (timer) {\n      if (_lineIndex < _panicLogs.length) {\n        setState(() {\n          _lines.add(_panicLogs[_lineIndex]);\n          _lineIndex++;\n          if (_panicLogs[_lineIndex - 1].contains(\"Kernel panic\")) {\n            _isPanic = true;\n          }\n        });\n        _scrollToBottom();\n      } else {\n        _timer?.cancel();\n      }\n    });\n  }\n\n  void _scrollToBottom() {\n    WidgetsBinding.instance.addPostFrameCallback((_) {\n      if (_scrollController.hasClients) {\n        _scrollController.animateTo(\n          _scrollController.position.maxScrollExtent,\n          duration: const Duration(milliseconds: 50),\n          curve: Curves.easeOut,\n        );\n      }\n    });\n  }\n\n  @override\n  void dispose() {\n    _timer?.cancel();\n    _scrollController.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      backgroundColor: Colors.black,\n      body: Stack(\n        children: [\n          Padding(\n            padding: const EdgeInsets.all(20.0),\n            child: ListView.builder(\n              controller: _scrollController,\n              itemCount: _lines.length + 1,\n              itemBuilder: (context, index) {\n                if (index == _lines.length) {\n                  return _isPanic\n                      ? _buildRebootPrompt()\n                      : const SizedBox.shrink();\n                }\n                return Text(\n                  _lines[index],\n                  style: const TextStyle(\n                    color: Colors.white,\n                    fontFamily: 'JetBrainsMono',\n                    fontSize: 14,\n                  ),\n                );\n              },\n            ),\n          ),\n          IgnorePointer(\n            child: Container(\n              decoration: BoxDecoration(\n                gradient: LinearGradient(\n                  begin: Alignment.topCenter,\n                  end: Alignment.bottomCenter,\n                  colors: [\n                    Colors.white.withOpacity(0.05),\n                    Colors.transparent,\n                    Colors.black.withOpacity(0.05),\n                  ],\n                  stops: const [0, 0.5, 1],\n                ),\n              ),\n              child: _buildScanlines(),\n            ),\n          ),\n          if (_isPanic) const IgnorePointer(child: FlickeringOverlay()),\n          if (_isPanic) IgnorePointer(child: GlitchEffect()),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildScanlines() {\n    return LayoutBuilder(\n      builder: (context, constraints) {\n        return Column(\n          children: List.generate(\n            (constraints.maxHeight / 3).floor(),\n            (index) =>\n                Container(height: 1, color: Colors.black.withOpacity(0.3)),\n          ),\n        );\n      },\n    );\n  }\n\n  Widget _buildRebootPrompt() {\n    return Padding(\n      padding: const EdgeInsets.symmetric(vertical: 40.0),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          const Text(\n            \"\\n[!] KERNEL PANIC: VFS: Unable to mount root fs\",\n            style: TextStyle(\n              color: Colors.redAccent,\n              fontFamily: 'JetBrainsMono',\n              fontSize: 18,\n              fontWeight: FontWeight.bold,\n            ),\n          ),\n          const SizedBox(height: 20),\n          const Text(\n            \"404 - SYSTEM ERROR\\n------------------\\nTHE REQUESTED PAGE DOES NOT EXIST IN THE CURRENT NAMESPACE.\",\n            style: TextStyle(\n              color: Colors.white,\n              fontFamily: 'JetBrainsMono',\n              fontSize: 14,\n            ),\n          ),\n          const SizedBox(height: 40),\n          MouseRegion(\n            cursor: SystemMouseCursors.click,\n            child: GestureDetector(\n              onTap: () => Navigator.of(context).pushReplacementNamed('/'),\n              child: Container(\n                padding: const EdgeInsets.symmetric(\n                  horizontal: 20,\n                  vertical: 10,\n                ),\n                decoration: BoxDecoration(\n                  border: Border.all(color: Colors.white),\n                  color: Colors.transparent,\n                ),\n                child: const Text(\n                  \"REBOOT_SYSTEM_FORCE\",\n                  style: TextStyle(\n                    color: Colors.white,\n                    fontFamily: 'JetBrainsMono',\n                    fontWeight: FontWeight.bold,\n                  ),\n                ),\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass GlitchEffect extends StatefulWidget {\n  const GlitchEffect({super.key});\n\n  @override\n  State<GlitchEffect> createState() => _GlitchEffectState();\n}\n\nclass _GlitchEffectState extends State<GlitchEffect>\n    with SingleTickerProviderStateMixin {\n  late AnimationController _controller;\n  final Random _random = Random();\n\n  @override\n  void initState() {\n    super.initState();\n    _controller = AnimationController(\n      vsync: this,\n      duration: const Duration(milliseconds: 200),\n    )..repeat();\n  }\n\n  @override\n  void dispose() {\n    _controller.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return AnimatedBuilder(\n      animation: _controller,\n      builder: (context, child) {\n        if (_random.nextDouble() > 0.1) return const SizedBox.shrink();\n\n        return Stack(\n          children: [\n            Positioned(\n              top: _random.nextDouble() * MediaQuery.of(context).size.height,\n              left: 0,\n              right: 0,\n              child: Container(\n                height: _random.nextDouble() * 20,\n                color: Colors.white.withOpacity(0.1),\n              ),\n            ),\n            Positioned(\n              left: _random.nextDouble() * MediaQuery.of(context).size.width,\n              top: 0,\n              bottom: 0,\n              child: Container(\n                width: _random.nextDouble() * 2,\n                color: Colors.red.withOpacity(0.1),\n              ),\n            ),\n          ],\n        );\n      },\n    );\n  }\n}\n\nclass FlickeringOverlay extends StatefulWidget {\n  const FlickeringOverlay({super.key});\n\n  @override\n  State<FlickeringOverlay> createState() => _FlickeringOverlayState();\n}\n\nclass _FlickeringOverlayState extends State<FlickeringOverlay>\n    with SingleTickerProviderStateMixin {\n  late AnimationController _controller;\n  final Random _random = Random();\n\n  @override\n  void initState() {\n    super.initState();\n    _controller = AnimationController(\n      vsync: this,\n      duration: const Duration(milliseconds: 100),\n    )..repeat();\n  }\n\n  @override\n  void dispose() {\n    _controller.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return AnimatedBuilder(\n      animation: _controller,\n      builder: (context, child) {\n        return Container(\n          color: Colors.red.withOpacity(_random.nextDouble() * 0.03),\n        );\n      },\n    );\n  }\n}\n",
  "lib/pages/home/home_page.dart": "import 'dart:async';\n\nimport 'package:archbtw_sh/games/super_archbtw.dart';\nimport 'package:archbtw_sh/global/colors.dart';\nimport 'package:archbtw_sh/global/site_music_controller.dart';\nimport 'package:archbtw_sh/pages/overheat/overheat_page.dart';\nimport 'package:archbtw_sh/widgets/christmas_countdown.dart';\nimport 'package:archbtw_sh/widgets/social_icons.dart';\nimport 'package:flutter/material.dart';\nimport 'package:font_awesome_flutter/font_awesome_flutter.dart';\n\nclass HomePage extends StatefulWidget {\n  const HomePage({super.key});\n\n  @override\n  State<HomePage> createState() => _HomePageState();\n}\n\nclass _HomePageState extends State<HomePage>\n    with AutomaticKeepAliveClientMixin {\n  static const String _fullText = \"hi. i'm archBTW.\";\n  static const List<Color> _cursorColors = [\n    kAccentColor,\n    kHolidayRed,\n    kHolidayGreen,\n    kHolidayGold,\n  ];\n\n  String _currentText = '';\n  int _currentIndex = 0;\n  bool _showCursor = true;\n  int _cursorColorIndex = 0;\n  bool _typingComplete = false;\n\n  late final Timer _typingTimer;\n  Timer? _cursorTimer;\n\n  @override\n  bool get wantKeepAlive => true;\n\n  @override\n  void initState() {\n    super.initState();\n\n    _typingTimer = Timer.periodic(const Duration(milliseconds: 150), (timer) {\n      if (_currentIndex < _fullText.length) {\n        if (mounted) {\n          setState(() {\n            _currentText = _fullText.substring(0, _currentIndex + 1);\n            _currentIndex++;\n          });\n        }\n      } else {\n        timer.cancel();\n        if (mounted) {\n          setState(() {\n            _typingComplete = true;\n          });\n        }\n        _cursorTimer = Timer.periodic(const Duration(milliseconds: 500), (\n          timer,\n        ) {\n          if (mounted) {\n            setState(() {\n              _showCursor = !_showCursor;\n              if (_showCursor) {\n                _cursorColorIndex =\n                    (_cursorColorIndex + 1) % _cursorColors.length;\n              }\n            });\n          }\n        });\n      }\n    });\n  }\n\n  @override\n  void dispose() {\n    _typingTimer.cancel();\n    _cursorTimer?.cancel();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    super.build(context);\n\n    final screenWidth = MediaQuery.of(context).size.width;\n    final bool isDesktop = screenWidth >= 768.0;\n\n    final double titleFontSize = isDesktop ? 36 : 24;\n    final double iconSize = isDesktop ? 24 : 18;\n    final double socialSpacing = isDesktop ? 24 : (screenWidth < 360 ? 6 : 14);\n    final double bottomPadding = isDesktop ? 16 : 10;\n    final Color activeCursorColor = _cursorColors[_cursorColorIndex];\n\n    return Column(\n      children: [\n        Expanded(\n          child: Center(\n            child: Column(\n              mainAxisSize: MainAxisSize.min,\n              children: [\n                Text.rich(\n                  TextSpan(\n                    children: [\n                      TextSpan(\n                        text: _currentText,\n                        style: TextStyle(\n                          color: kTextColor,\n                          fontSize: titleFontSize,\n                          fontWeight: FontWeight.bold,\n                          letterSpacing: 1.5,\n                          fontFamily: 'JetBrainsMono',\n                        ),\n                      ),\n                      TextSpan(\n                        text: _showCursor ? '|' : ' ',\n                        style: TextStyle(\n                          color: _showCursor\n                              ? activeCursorColor\n                              : Colors.transparent,\n                          fontSize: titleFontSize,\n                          fontWeight: FontWeight.bold,\n                          fontFamily: 'JetBrainsMono',\n                        ),\n                      ),\n                    ],\n                  ),\n                ),\n                const SizedBox(height: 10),\n                AnimatedOpacity(\n                  opacity: _typingComplete ? 1.0 : 0.0,\n                  duration: const Duration(milliseconds: 600),\n                  child: Text.rich(\n                    TextSpan(\n                      style: TextStyle(\n                        fontSize: isDesktop ? 13 : 11,\n                        fontFamily: 'JetBrainsMono',\n                        letterSpacing: 1.2,\n                      ),\n                      children: [\n                        TextSpan(\n                          text: '* ',\n                          style: TextStyle(\n                            color: kHolidayGold.withValues(alpha: 0.75),\n                          ),\n                        ),\n                        TextSpan(\n                          text: 'happy holidays',\n                          style: TextStyle(\n                            color: Colors.white.withValues(alpha: 0.38),\n                          ),\n                        ),\n                        TextSpan(\n                          text: ' *',\n                          style: TextStyle(\n                            color: kHolidayGreen.withValues(alpha: 0.75),\n                          ),\n                        ),\n                      ],\n                    ),\n                  ),\n                ),\n              ],\n            ),\n          ),\n        ),\n        ListenableBuilder(\n          listenable: SiteMusicController.instance,\n          builder: (context, child) {\n            final bool toastVisible =\n                SiteMusicController.instance.shouldShowFloatingToast;\n            return AnimatedPadding(\n              duration: const Duration(milliseconds: 220),\n              curve: Curves.easeOutCubic,\n              padding: EdgeInsets.only(\n                bottom: bottomPadding + (toastVisible ? 68.0 : 0.0),\n              ),\n              child: child,\n            );\n          },\n          child: Column(\n            mainAxisSize: MainAxisSize.min,\n            children: [\n              Row(\n                mainAxisAlignment: MainAxisAlignment.center,\n                children: [\n                  SocialIcon(\n                    icon: FontAwesomeIcons.linux,\n                    url: 'https://welledumacated.dev',\n                    iconSize: iconSize,\n                  ),\n                  SizedBox(width: socialSpacing),\n                  SocialIcon(\n                    icon: FontAwesomeIcons.computer,\n                    url: 'https://archerwoods.dev',\n                    iconSize: iconSize,\n                  ),\n                  SizedBox(width: socialSpacing),\n                  SocialIcon(\n                    icon: FontAwesomeIcons.github,\n                    url: 'https://www.github.com/archieBTW',\n                    iconSize: iconSize,\n                  ),\n                  SizedBox(width: socialSpacing),\n                  SocialIcon(\n                    icon: FontAwesomeIcons.code,\n                    iconSize: iconSize,\n                    onPressed: () {\n                      Navigator.pushNamed(context, '/source');\n                    },\n                  ),\n                  SizedBox(width: socialSpacing),\n                  SocialIcon(\n                    key: const Key('angel_tree_button'),\n                    icon: FontAwesomeIcons.tree,\n                    url: 'https://www.salvationarmyusa.org/walmart-angel-tree/',\n                    iconSize: iconSize,\n                    tooltip: 'adopt an angel / family',\n                    hoverColor: kHolidayGreen,\n                  ),\n                  SizedBox(width: socialSpacing),\n                  SocialIcon(\n                    icon: FontAwesomeIcons.fire,\n                    iconSize: iconSize,\n                    tooltip: 'overheat',\n                    hoverColor: const Color(0xFFFF6F00),\n                    onPressed: () {\n                      Navigator.push(\n                        context,\n                        PageRouteBuilder(\n                          opaque: false,\n                          pageBuilder:\n                              (context, animation, secondaryAnimation) {\n                                return const OverheatPage();\n                              },\n                          transitionsBuilder:\n                              (context, animation, secondaryAnimation, child) {\n                                return FadeTransition(\n                                  opacity: animation,\n                                  child: child,\n                                );\n                              },\n                        ),\n                      );\n                    },\n                  ),\n                  SizedBox(width: socialSpacing),\n                  SocialIcon(\n                    key: const Key('okc_game_button'),\n                    icon: FontAwesomeIcons.gamepad,\n                    iconSize: iconSize,\n                    tooltip: 'play super_archbtw.sh',\n                    hoverColor: kAccentColor,\n                    onPressed: () {\n                      Navigator.push(\n                        context,\n                        MaterialPageRoute(\n                          builder: (context) => const SuperArchBtw(),\n                        ),\n                      );\n                    },\n                  ),\n                ],\n              ),\n              SizedBox(height: isDesktop ? 10.0 : 6.0),\n              const ChristmasCountdown(),\n            ],\n          ),\n        ),\n      ],\n    );\n  }\n}\n",
  "lib/pages/merch/merch__page.dart": "import 'package:archbtw_sh/global/colors.dart';\nimport 'package:archbtw_sh/pages/merch/merch_grid_item.dart';\nimport 'package:archbtw_sh/pages/merch/merch_item_list.dart';\nimport 'package:flutter/material.dart';\nimport 'package:url_launcher/url_launcher.dart';\n\nconst String kStoreUrl = 'https://www.teepublic.com/user/archbtw';\n\nclass MerchPage extends StatelessWidget {\n  const MerchPage({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      body: CustomScrollView(\n        slivers: [\n          SliverPadding(\n            padding: const EdgeInsets.all(16.0),\n            sliver: SliverGrid.builder(\n              gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(\n                maxCrossAxisExtent: 250.0,\n                crossAxisSpacing: 16.0,\n                mainAxisSpacing: 16.0,\n                childAspectRatio: 0.75,\n              ),\n              itemCount: merchItems.length,\n              itemBuilder: (context, index) {\n                return MerchGridItem(item: merchItems[index]);\n              },\n            ),\n          ),\n          SliverToBoxAdapter(\n            child: Padding(\n              padding: const EdgeInsets.fromLTRB(16.0, 8.0, 16.0, 32.0),\n              child: Center(\n                child: TextButton(\n                  onPressed: () => launchUrl(Uri.parse(kStoreUrl)),\n                  style: TextButton.styleFrom(\n                    foregroundColor: kAccentColor,\n                    textStyle: TextStyle(\n                      fontSize: 16,\n                      fontWeight: FontWeight.bold,\n                      fontFamily: 'JetBrainsMono',\n                    ),\n                  ),\n                  child: const Text('View More on TeePublic'),\n                ),\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\n",
  "lib/pages/merch/merch_grid_item.dart": "import 'dart:ui';\n\nimport 'package:archbtw_sh/global/colors.dart';\nimport 'package:archbtw_sh/global/helpers.dart';\nimport 'package:archbtw_sh/pages/merch/merch_item.dart';\nimport 'package:archbtw_sh/widgets/loading_waveform.dart';\nimport 'package:flutter/material.dart';\n\nclass MerchGridItem extends StatelessWidget {\n  final MerchItem item;\n  const MerchGridItem({super.key, required this.item});\n\n  @override\n  Widget build(BuildContext context) {\n    return InkWell(\n      onTap: () => openUrl(item.productUrl),\n      borderRadius: BorderRadius.circular(12.0),\n      child: ClipRRect(\n        borderRadius: BorderRadius.circular(12.0),\n        child: Stack(\n          children: [\n            BackdropFilter(\n              filter: ImageFilter.blur(sigmaX: 10.0, sigmaY: 10.0),\n              child: Container(\n                decoration: const BoxDecoration(color: Colors.transparent),\n              ),\n            ),\n            Card(\n              color: Colors.white.withOpacity(0.05),\n              elevation: 0,\n              clipBehavior: Clip.antiAlias,\n              shape: RoundedRectangleBorder(\n                side: BorderSide(\n                  color: Colors.white.withOpacity(0.1),\n                  width: 1,\n                ),\n                borderRadius: BorderRadius.circular(12.0),\n              ),\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.stretch,\n                children: [\n                  Expanded(\n                    child: Image.asset(\n                      item.imageUrl,\n                      fit: BoxFit.cover,\n                      frameBuilder:\n                          (context, child, frame, wasSynchronouslyLoaded) {\n                            if (wasSynchronouslyLoaded || frame != null) {\n                              return child;\n                            }\n                            return Container(\n                              color: Colors.white.withOpacity(0.02),\n                              child: const Center(\n                                child: WaveformLoader(height: 25, barWidth: 3),\n                              ),\n                            );\n                          },\n                      errorBuilder: (context, error, stackTrace) {\n                        return Container(\n                          color: Colors.grey[800],\n                          child: const Center(\n                            child: Icon(\n                              Icons.image_not_supported_outlined,\n                              color: kTextColor,\n                              size: 50,\n                            ),\n                          ),\n                        );\n                      },\n                    ),\n                  ),\n                  SizedBox(\n                    height: 85.0,\n                    child: Padding(\n                      padding: const EdgeInsets.all(12.0),\n                      child: Column(\n                        crossAxisAlignment: CrossAxisAlignment.start,\n                        mainAxisAlignment: MainAxisAlignment.center,\n                        children: [\n                          Text(\n                            item.name,\n                            style: const TextStyle(\n                              color: kTextColor,\n                              fontWeight: FontWeight.bold,\n                              fontSize: 14,\n                              fontFamily: 'JetBrainsMono',\n                            ),\n                            maxLines: 2,\n                            overflow: TextOverflow.ellipsis,\n                          ),\n                          const SizedBox(height: 4),\n                          Text(\n                            item.price,\n                            style: const TextStyle(\n                              color: kAccentColor,\n                              fontSize: 12,\n                              fontWeight: FontWeight.w500,\n                              fontFamily: 'JetBrainsMono',\n                            ),\n                          ),\n                        ],\n                      ),\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n",
